
const $=s=>document.querySelector(s),root=$('#root');let rulesRead=false;let advertiserLoginMode=false;let state={token:sessionStorage.getItem('taskoToken')||localStorage.getItem('taskoToken'),user:null,view:'dashboard',portal:localStorage.getItem('taskoPortal')||'user',preview:false,taskFilter:'all',rewardCategory:'all'};
function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function fmt(n){return Number(n||0).toLocaleString('en-US')}function date(x){return x?new Date(x).toLocaleString('ar-JO',{dateStyle:'medium',timeStyle:'short'}):'—'}function levelInfo(x){const v=Number(x||0);if(v>=7000)return {name:'Diamond',min:7000,next:null,cls:'diamond'};if(v>=3000)return {name:'Gold',min:3000,next:7000,cls:'gold'};if(v>=1000)return {name:'Silver',min:1000,next:3000,cls:'silver'};return {name:'Bronze',min:0,next:1000,cls:'bronze'}}
async function api(path,opts={}){const h={'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{})};const r=await fetch(path,{...opts,headers:{...h,...(opts.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'حدث خطأ غير متوقع');return d}function toast(x){const e=document.createElement('div');e.className='toast';e.textContent=translateUI(x);document.body.appendChild(e);setTimeout(()=>e.remove(),3000)}function eye(id){return `<button type="button" class="pwEye" aria-label="إظهار كلمة المرور" onclick="togglePw('${id}',this)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.7"/></svg></button>`}function togglePw(id,b){const e=$('#'+id);const show=e.type==='password';e.type=show?'text':'password';b.setAttribute('aria-label',show?'إخفاء كلمة المرور':'إظهار كلمة المرور');b.innerHTML=show?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18M10.6 10.6a2.7 2.7 0 0 0 3.8 3.8M9.9 5.2A10.8 10.8 0 0 1 12 5c6 0 9.5 7 9.5 7a17.6 17.6 0 0 1-3.2 3.9M6.2 6.3C3.9 8 2.5 12 2.5 12s3.5 6 9.5 6c1.5 0 2.8-.4 4-1.1"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.7"/></svg>'}
function levelLabel(x){const id=x?.levelMinId||x?.levelId;if(id){const names={bronze:'Bronze',silver:'Silver',gold:'Gold',diamond:'Diamond'};return names[id]||'Bronze'}const n=Number(x?.levelMin||0);return n>=15000?'Diamond':n>=5000?'Gold':n>=1000?'Silver':'Bronze'}
function auth(){const path=location.pathname.replace(/\/$/,'')||'/';if(path==='/admin'){state.portal='admin'}else if(path==='/advertiser'){state.portal='advertiser'}else{state.portal='user'};const special=state.portal!=='user';if(state.portal==='advertiser'&&!advertiserLoginMode)return advertiserLanding();root.innerHTML=`<div class=auth><div class=authbox><div class=space><div><div class=authBrand>${state.portal==='advertiser'?'Tasko for Business':state.portal==='admin'?'Tasko Control Center':'Tasko'}</div><div class=muted>${state.portal==='advertiser'?'بوابة الشركات والمعلنين':state.portal==='admin'?'بوابة الإدارة والتشغيل':'Do Tasks. Earn More.'}</div></div><span class=pill>${state.portal==='advertiser'?'ADVERTISER':state.portal==='admin'?'ADMIN':'MEMBER'}</span></div><div class=tabs style="margin:24px 0"><button id=loginTab class=active onclick="authMode('login')">تسجيل الدخول</button>${special?'':`<button id=signupTab onclick="authMode('signup')">إنشاء حساب</button>`}</div><div id=authForm></div>${state.portal==='user'?`<div class=card style="margin-top:16px;background:#f7fafc"><div class=space><div><b>للشركات والمعلنين</b><div class=muted style="font-size:13px;margin-top:4px">لديكم بوابة مستقلة للحملات والنتائج.</div></div><button class="btn dark" onclick="location.href='/advertiser'">أعلن معنا</button></div></div>`:''}</div></div>`;authMode('login')}
function authMode(m){$('#loginTab').classList.toggle('active',m==='login');$('#signupTab')?.classList.toggle('active',m==='signup');const saved=localStorage.getItem('taskoRememberEmail')||'';if(m==='login'){$('#authForm').innerHTML=`<div class=notice>${state.portal==='admin'?'الدخول مخصص لـ Owner / Admin فقط.':state.portal==='advertiser'?'الدخول مخصص للحسابات الإعلانية المعتمدة.':'هذه هي بوابة المستخدمين للمهام والمكافآت.'}</div><div class=field><label>البريد الإلكتروني</label><input id=email class=input type=email autocomplete=email value="${esc(saved)}"></div><div class=field style="position:relative"><label>كلمة المرور</label><input id=password class=input type=password autocomplete=current-password>${eye('password')}</div><label class=checkRow><input id=rememberDevice type=checkbox ${saved?'checked':''}> تذكرني على هذا الجهاز</label><button class=btn style="width:100%;margin-top:10px" onclick="login()">${state.portal==='admin'?'دخول إلى لوحة الإدارة':state.portal==='advertiser'?'دخول إلى بوابة المعلن':'دخول إلى حسابي'}</button><button class="btn ghost" style="width:100%;margin-top:8px" onclick="forgotPassword()">نسيت كلمة المرور؟</button>`;return}const countries={Jordan:{label:'الأردن',cities:['Amman','Irbid','Zarqa','Aqaba','Salt','Madaba','Jerash','Mafraq','Karak','Tafilah','Ma’an','Ajloun']},SaudiArabia:{label:'السعودية',cities:['Riyadh','Jeddah','Dammam','Mecca','Medina','Khobar','Abha','Taif']},UnitedArabEmirates:{label:'الإمارات',cities:['Dubai','Abu Dhabi','Sharjah','Ajman','Al Ain','Ras Al Khaimah']},Egypt:{label:'مصر',cities:['Cairo','Giza','Alexandria','Mansoura','Tanta','Port Said','Suez','Aswan']},Palestine:{label:'فلسطين',cities:['Ramallah','Nablus','Hebron','Gaza','Jericho','Jenin']},Iraq:{label:'العراق',cities:['Baghdad','Basra','Erbil','Mosul','Najaf','Karbala']},Kuwait:{label:'الكويت',cities:['Kuwait City','Hawalli','Salmiya','Farwaniya']},Qatar:{label:'قطر',cities:['Doha','Al Rayyan','Al Wakrah']},Bahrain:{label:'البحرين',cities:['Manama','Riffa','Muharraq']},Oman:{label:'عُمان',cities:['Muscat','Salalah','Sohar','Nizwa']},Lebanon:{label:'لبنان',cities:['Beirut','Tripoli','Sidon','Zahle']},Morocco:{label:'المغرب',cities:['Rabat','Casablanca','Marrakesh','Fes','Tangier']},Algeria:{label:'الجزائر',cities:['Algiers','Oran','Constantine','Blida']},Tunisia:{label:'تونس',cities:['Tunis','Sfax','Sousse','Bizerte']}};const sourceOpts=['Instagram','Facebook','TikTok','YouTube','Social Media','Friend','Advertisement','Search Engine','Website','Online Community/Group','University/School','Company/Other','AI Tool','Other'];$('#authForm').innerHTML=`<div class=notice>قبل إنشاء الحساب، اقرأ الشروط وقواعد Fair Play والخصوصية، وأدخل بياناتك الحقيقية.</div><div class=field><label>الاسم</label><input id=name class=input autocomplete=name></div><div class=field><label>البريد الإلكتروني</label><input id=email class=input type=email autocomplete=email></div><div class=field><label>رقم الهاتف</label><input id=phone class=input autocomplete=tel placeholder="07xxxxxxxx"></div><div class=grid2><div class=field><label>الدولة</label><select id=country class=input onchange="updateCities()"><option value="">اختر الدولة</option>${Object.entries(countries).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></div><div class=field><label>المدينة</label><select id=city class=input disabled><option value="">اختر المدينة</option></select></div></div><div class=grid2><div class=field><label>تاريخ الميلاد</label><input id=dateOfBirth class=input type=date></div><div class=field><label>الجنس</label><select id=gender class=input><option value="">اختر</option><option value="Male">ذكر</option><option value="Female">أنثى</option></select></div></div><div class=field><label>كيف سمعت عن Tasko؟</label><select id=acquisitionSource class=input onchange="$('#acqOtherWrap').style.display=this.value==='Other'?'block':'none'"><option value="">اختر مصدراً واحداً</option>${sourceOpts.map(x=>`<option value="${x}">${x}</option>`).join('')}</select></div><div id=acqOtherWrap class=field style="display:none"><label>اذكر المصدر</label><input id=acquisitionOther class=input></div><div class=field style="position:relative"><label>كلمة المرور</label><input id=password class=input type=password oninput="pwCheck()" autocomplete=new-password>${eye('password')}</div><div id=pwChecklist style="font-size:12px;margin:8px 0"></div><div class=field style="position:relative"><label>تأكيد كلمة المرور</label><input id=passwordConfirm class=input type=password autocomplete=new-password>${eye('passwordConfirm')}</div><div class=field><label>كود الإحالة (اختياري)</label><input id=ref class=input></div><div class=card style="background:#f8fafc"><label style="display:block"><input type=checkbox id=consent> أوافق على الشروط والخصوصية وقواعد Fair Play بعد قراءتها.</label><label class=checkRow style="margin-top:10px"><input type=checkbox id=demographicConsent> أقر أن تاريخ الميلاد والجنس والدولة والمدينة وباقي البيانات تخصني وحقيقية، وأن تقديم بيانات كاذبة أو التلاعب قد يؤدي إلى تقييد أو تعليق أو إنهاء الحساب وفقدان المكافآت وفق الشروط.</label><button class="btn ghost" style="margin-top:10px" onclick="showRules()">قراءة الشروط والقواعد</button></div><button class=btn style="width:100%;margin-top:10px" onclick="register()">إنشاء الحساب</button>`;window.__taskoCountries=countries}
function updateCities(){const c=$('#country')?.value,el=$('#city');if(!el)return;const cities=window.__taskoCountries?.[c]?.cities||[];el.disabled=!cities.length;el.innerHTML='<option value="">اختر المدينة</option>'+cities.map(x=>`<option value="${x}">${x}</option>`).join('')}
function setPortal(p){location.href=p==='admin'?'/admin':p==='advertiser'?'/advertiser':'/'}function pwCheck(){const p=$('#password')?.value||'';const a=[['8 أحرف على الأقل',p.length>=8],['حرف كبير',/[A-Z]/.test(p)],['حرف صغير',/[a-z]/.test(p)],['رقم',/\d/.test(p)],['رمز خاص',/[^A-Za-z0-9]/.test(p)]];$('#pwChecklist').innerHTML=a.map(x=>`<span class="pill ${x[1]?'green':''}">${x[1]?'✓':'•'} ${x[0]}</span>`).join(' ')}
async function forgotPassword(){const email=prompt('أدخل البريد الإلكتروني للحساب');if(!email)return;try{const d=await api('/api/password/forgot',{method:'POST',body:JSON.stringify({email})});if(d.devResetToken){const token=prompt('رمز الاستعادة التجريبي (للتطوير فقط):',d.devResetToken);if(!token)return;const np=prompt('كلمة المرور الجديدة');const cp=prompt('تأكيد كلمة المرور الجديدة');if(!np||np!==cp)return toast('كلمتا المرور غير متطابقتين');await api('/api/password/reset',{method:'POST',body:JSON.stringify({token,newPassword:np})});toast('تم تغيير كلمة المرور. سجل الدخول من جديد.')}else toast(d.message||'إذا كان الحساب موجوداً ستصل تعليمات الاستعادة.')}catch(e){toast(e.message)}}
async function register(){try{if(!rulesRead)return toast('افتح قواعد الاستخدام واقرأها أولاً');if(!$('#consent').checked||!$('#demographicConsent').checked)return toast('يجب الموافقة على الشروط وإقرار صحة البيانات');if($('#password').value!==$('#passwordConfirm').value)return toast('كلمتا المرور غير متطابقتين');const d=await api('/api/register',{method:'POST',body:JSON.stringify({name:$('#name').value,email:$('#email').value,phone:$('#phone').value,password:$('#password').value,passwordConfirm:$('#passwordConfirm').value,ref:$('#ref').value,country:$('#country').value,city:$('#city').value,dateOfBirth:$('#dateOfBirth').value,gender:$('#gender').value,acquisitionSource:$('#acquisitionSource').value,acquisitionOther:$('#acquisitionOther')?.value||'',consent:true,demographicConsent:true,rulesRead:true})});toast('تم إنشاء الحساب بنجاح');authMode('login');$('#email').value=d.user.email}catch(e){toast(e.message)}}
async function login(){try{const p=state.portal,email=$('#email').value,remember=$('#rememberDevice')?.checked;const d=await api('/api/login/'+p,{method:'POST',body:JSON.stringify({email,password:$('#password').value})});state.token=d.token;state.user=d.user;sessionStorage.setItem('taskoToken',d.token);if(remember){localStorage.setItem('taskoToken',d.token);localStorage.setItem('taskoRememberEmail',email)}else{localStorage.removeItem('taskoToken');localStorage.removeItem('taskoRememberEmail')}render()}catch(e){toast(e.message)}}
function showRules(){root.insertAdjacentHTML('beforeend',`<div class=fullModal id=rulesModal><div class=fullModalHead><div><h2>شروط الاستخدام وقواعد Fair Play</h2><div class=muted>اقرأ الصفحة كاملة قبل الموافقة</div></div><button class="btn ghost" onclick="$('#rulesModal').remove()">إغلاق</button></div><div class=fullModalBody><h3>الحساب</h3><p>حساب واحد لكل شخص، ولا يجوز مشاركة الحساب أو إنشاء حسابات مكررة للتحايل.</p><h3>المهام</h3><p>تنفيذ المهام فعلياً وفق شروطها. يمنع التلاعب بالتتبع أو إثباتات مزيفة أو استغلال الثغرات أو أدوات آلية غير مصرح بها.</p><h3>الإحالات والمكافآت</h3><p>يمنع إنشاء إحالات وهمية أو ذاتية أو تكرار المكافآت.</p><h3>المخالفات</h3><p>قد ينتج عن المخالفة تنبيه أو تقييد أو تعليق أو حظر حسب الشدة والتكرار، ويمكن طلب مراجعة القرار.</p><h3>الباقات</h3><p>الباقات خدمات وصول وميزات وليست استثماراً ولا تضمن عائداً مالياً.</p><h3>الخصوصية</h3><p>تُستخدم البيانات اللازمة لتشغيل الحساب والمهام والسحب والدعم والحماية من الاحتيال وفق السياسة المعتمدة.</p></div><div class=fullModalFoot><button class=btn style="width:100%" onclick="rulesRead=true;$('#consent').checked=true;$('#rulesModal').remove();toast('تم تسجيل القراءة والموافقة')">أوافق على الشروط وقواعد Fair Play</button></div></div>`)}
function advertiserLanding(){root.innerHTML=`<div class=auth><div class=authbox><div class=authBrand>Tasko for Business</div><p class=subtitle>إدارة الحملات والنتائج والتحويلات.</p><div class=grid2><button class=portalBtn onclick="advertiserLogin()">📣 أنا معلن بالفعل<br><span class=muted>تسجيل الدخول مباشرة</span></button><button class=portalBtn onclick="advertiserRequest()">🏢 أريد أن أصبح معلناً<br><span class=muted>طلب حساب شركة</span></button></div><button class="btn ghost" style="margin-top:14px" onclick="goBack()">العودة</button></div></div>`}
function advertiserLogin(){advertiserLoginMode=true;auth()}async function advertiserRequest(){root.innerHTML=`<div class=auth><div class=authbox style="width:min(760px,100%)"><h1>طلب حساب معلن</h1><p class=subtitle>أرسل معلومات الشركة الأساسية، وبعد المراجعة يتم التواصل معك لإكمال أي تفاصيل إضافية.</p><div class=grid2><div class=field><label>اسم الشركة / النشاط</label><input id=rc class=input></div><div class=field><label>المسؤول</label><input id=rn class=input></div><div class=field><label>المسمى الوظيفي</label><input id=rj class=input></div><div class=field><label>البريد</label><input id=re class=input type=email></div><div class=field><label>الهاتف</label><input id=rp class=input></div><div class=field><label>نوع النشاط / المجال</label><input id=rbt class=input></div></div><div class=field><label>نبذة قصيرة عن الشركة / النشاط</label><textarea id=rd class=input rows=4></textarea></div><div class=notice>هذه المرحلة لفتح حساب المعلن فقط. تفاصيل الحملات والميزانية والمحتوى وشروط المهمة تُرسل لاحقاً من بوابة المعلن.</div><div class=row style="margin-top:14px"><button class=btn onclick="submitAdvertiserRequest()">إرسال الطلب</button><button class="btn ghost" onclick="advertiserLanding()">رجوع</button></div></div></div>`}
async function submitAdvertiserRequest(){try{const d=await api('/api/advertiser/request',{method:'POST',body:JSON.stringify({company:$('#rc').value,contact:$('#rn').value,jobTitle:$('#rj').value,email:$('#re').value,phone:$('#rp').value,businessType:$('#rbt').value,description:$('#rd').value})});toast('تم إرسال الطلب للمراجعة');advertiserLanding()}catch(e){toast(e.message)}}
function isAdmin(){return ['owner','admin'].includes(state.user?.role)}function go(v){state.view=v;document.querySelector('.shell')?.classList.remove('open');render()}function nav(items){return `<div class=nav>${items.map(x=>`<button class="${state.view===x[0]?'active':''}" onclick="go('${x[0]}')">${x[1]}</button>`).join('')}</div>`}function layout(content){const previewMode=!!state.preview,admin=isAdmin()&&!previewMode,items=admin&&!previewMode?[['dashboard','⌂  لوحة التحكم'],['users','👥 المستخدمون'],['admins','🛡️ إدارة الأدمن'],['advertisers','📣 المعلنون'],['campaigns','📊 الحملات'],['tasks','✓ المهام'],['withdrawals','💳 السحوبات'],['support','💬 الدعم والتذاكر'],['fraud','⚠️ المخالفات'],['reports','▥ التقارير والتحليلات'],['activities','⌁ سجل العمليات'],['audit','◷ سجل التدقيق'],['settings','⚙ مركز التحكم'],['packagesAdmin','💳 إدارة الباقات'],['rewardsAdmin','🎁 إدارة المكافآت'],['sandbox','🧪 Test Center'],['preview','👁 Preview as User']]:state.portal==='advertiser'?[['dashboard','⌂ لوحة المعلن'],['campaigns','📊 حملاتي'],['account','◉ معلومات الحساب']]:[['dashboard','⌂ الرئيسية'],['tasks','✓ المهام'],['packages','◇ الباقات'],['rewards','🎁 متجر المكافآت'],['wallet','💳 المحفظة'],['referrals','↗ الإحالات'],['notifications','🔔 الإشعارات'],['support','💬 الدعم'],['fairplay','✓ Fair Play'],['profile','◉ الملف الشخصي']];const initial=(state.user?.name||'T')[0].toUpperCase();root.innerHTML=`<div class="app ${state.user?.package==='Premium'?'premiumTheme':''}"><header class=top>${previewMode?'<div class=preview>PREVIEW / SANDBOX</div>':''}<div class=row><button class=mobileMenu onclick="$('.shell').classList.toggle('open')">☰</button><div class=brand>Task<span>o</span></div></div><div class=topUser><div class=avatar>${esc(initial)}</div><span>${esc(state.user?.name||'')}</span>${previewMode?'<button class="btn danger" onclick="exitPreview()">إنهاء المعاينة</button>':''}<button class="btn ghost" onclick="logout()">خروج</button></div></header><div class=shell><aside><div style="padding:4px 10px 18px"><div style="font-size:13px;color:#8fa5bf">${admin?'CONTROL CENTER':state.portal==='advertiser'?'ADVERTISER PORTAL':'MEMBER AREA'}</div><b style="font-size:17px">${esc(state.user?.name||'')}</b></div>${nav(items)}</aside><main class=main>${content}</main></div></div>`;afterLayout()}
function afterLayout(){try{if($('#summaryBox'))loadSummary();if($('#usersBox'))loadUsers();if($('#adBox'))loadAdv();if($('#adminsBox')){loadAdmins();loadPerms()}if($('#advBox'))loadAdv();if($('#campBox')){loadCampaigns();loadAdvSelect()}if($('#taskAdminBox'))loadAdminTasks();if($('#wBox'))loadW();if($('#sBox'))loadSupport();if($('#fraudBox'))loadFraud();if($('#reportBox'))loadReports();if($('#activityBox'))loadActivities();if($('#auBox'))loadAudit();if($('#emergencyPanel'))loadSettings();if($('#pkgAdmin'))loadPackagesAdmin();if($('#rewardsAdminBox'))loadRewardsAdmin();if($('#advDash'))loadAdvDash();if($('#advAccountBox'))loadAdvertiserAccount();if($('#sbUser'))loadSandbox();if($('#userWithdrawals'))loadUserWithdrawals();if($('#wUser'))loadUserWithdrawals()}catch(e){console.error(e)}}
async function render(){if(!state.token)return auth();try{state.user=(await api('/api/me')).user}catch{sessionStorage.removeItem('taskoToken');localStorage.removeItem('taskoToken');state={token:null,user:null,view:'dashboard',portal:'user'};return auth()}if(state.preview)return previewUserRender();if(state.portal==='advertiser')return advertiserRender();if(isAdmin())return adminRender();return await userRender()}
function levelBlock(u){const l=levelInfo(u.xp),pct=l.next?Math.min(100,Math.max(0,(u.xp-l.min)/(l.next-l.min)*100)):100;return `<div class="levelBar level-${l.cls}"><div class=levelLine><div><small class=muted>مستوى الحساب</small><div class=levelName>${l.name}</div></div><span class=levelBadge>${l.name}</span></div><div class=progress><span style="width:${pct}%"></span></div><div class=space style="margin-top:8px;font-size:12px"><span>${fmt(u.xp)} XP</span><span>${l.next?fmt(l.next-u.xp)+' XP للمستوى التالي':'أعلى مستوى 🎉'}</span></div></div>`}
function previewUserRender(){const u={name:'Preview User',email:'preview@tasko.test',phone:'0790000000',accountState:'Normal',xp:1850,points:1250,cash:12,package:'Free',createdAt:new Date().toISOString()};const l=levelInfo(u.xp);let c;if(state.view==='dashboard')c=`<div class=hero><div class=preview>PREVIEW / SANDBOX</div><h1>مرحباً بك في Tasko 👋</h1><p>هذه معاينة كاملة لواجهة المستخدم. كل الأزرار والانتقالات هنا تجريبية ولا تؤثر على بيانات حقيقية.</p><button class=btn onclick="go('tasks')">استكشف المهام</button></div><div class=grid><div class=card metric><span class=kpi>Points</span><strong>${fmt(u.points)}</strong></div><div class=card metric><span class=kpi>Cash</span><strong>${fmt(u.cash)}</strong></div><div class=card metric><span class=kpi>XP</span><strong>${fmt(u.xp)}</strong></div><div class=card metric><span class=kpi>الباقة</span><strong>${esc(u.package)}</strong></div></div><div class=section>${levelBlock(u)}</div>`;else if(state.view==='tasks')c=`<div class=space><div><h1>المهام</h1><p class=subtitle>بيانات تجريبية داخل المعاينة.</p></div><span class=pill blue>3 مهام متاحة</span></div><div class=grid2 section><div class=card taskCard><h2>مشاهدة فيديو</h2><p class=muted>مهمة تجريبية.</p><div class=taskMeta><span class=reward>50 Points</span><span class=pill>+20 XP</span><span class=pill>~2 دقيقة</span></div><button class=btn onclick="toast('إجراء Sandbox فقط')">التفاصيل</button></div><div class=card taskCard><h2>استبيان قصير</h2><p class=muted>مهمة تجريبية.</p><div class=taskMeta><span class=reward>150 Points</span><span class=pill>+50 XP</span><span class=pill>~5 دقائق</span></div><button class=btn onclick="toast('إجراء Sandbox فقط')">التفاصيل</button></div><div class=card taskCard><h2>اختبار موقع</h2><p class=muted>متطلب Plus / Silver في البيانات التجريبية.</p><div class=taskMeta><span class=reward>300 Points</span><span class=pill>+100 XP</span></div><button class=btn ghost onclick="toast('غير مؤهل في هذا الحساب التجريبي')">التفاصيل</button></div></div>`;else if(state.view==='packages')c=`<h1>الباقات</h1><p class=subtitle>الباقات خدمات وصول وميزات.</p><div class=grid3 section><div class=card><h2>Free</h2><p>الوصول الأساسي</p></div><div class=card><h2>Plus</h2><p>مهام أكثر وأولوية أفضل</p></div><div class=card><h2>Premium</h2><p>أعلى أولوية وحدود أعلى</p></div></div>`;else if(state.view==='rewards')c=`<h1>متجر المكافآت</h1><p class=subtitle>بيانات تجريبية للنقاط والاسترداد.</p><div class=grid2 section><div class=card><h2>دونات مجانية</h2><p class=muted>عند 1000 Points وSilver+.</p><span class=reward>1000 Points</span></div><div class=card><h2>قسيمة شريك</h2><p class=muted>عرض تجريبي.</p><span class=pill>500 Points</span></div></div>`;else if(state.view==='wallet')c=`<h1>المحفظة</h1><p class=subtitle>Sandbox — لا توجد عمليات مالية حقيقية.</p><div class=grid2><div class=card metric><span class=kpi>Points</span><strong>${fmt(u.points)}</strong></div><div class=card metric><span class=kpi>Cash</span><strong>${fmt(u.cash)}</strong></div></div><div class=card section><h2>سجل السحب</h2><div class=empty>لا يوجد سجل سحب في المعاينة.</div></div>`;else if(state.view==='referrals')c=`<h1>الإحالات</h1><p class=subtitle>بيانات تجريبية.</p><div class=grid2><div class=card><h2>كودك</h2><div style="font-size:26px;font-weight:800;margin:12px 0">PREVIEW01</div><button class=btn onclick="toast('تم نسخ الرابط التجريبي')">نسخ الرابط</button></div><div class=card><h2>سجل الإحالات</h2><div class=empty>لا توجد إحالات في المعاينة.</div></div></div>`;else if(state.view==='notifications')c=`<h1>الإشعارات</h1><div class=card empty>لا توجد إشعارات في المعاينة.</div>`;else if(state.view==='support')c=`<h1>الدعم</h1><div class=card><h2>مركز الدعم</h2><p class=muted>فتح التذاكر في المعاينة لا يرسل أي بيانات.</p><button class=btn onclick="toast('Sandbox فقط')">فتح تذكرة تجريبية</button></div>`;else if(state.view==='fairplay')c=fairPlayPage();else c=`<h1>الملف الشخصي</h1><div class=grid2 section><div class=card><h2>Preview User</h2><p class=muted>هذا الحساب افتراضي للمعاينة فقط.</p><div class=detailList><div class=detailItem><small>الحالة</small><b>Normal</b></div><div class=detailItem><small>المستوى</small><b>${l.name}</b></div><div class=detailItem><small>الباقة</small><b>Free</b></div></div></div><div class=card>${levelBlock(u)}</div></div>`;layout(c)}function exitPreview(){state.preview=false;state.portal='admin';state.view='dashboard';render()}async function userRender(){const u=state.user;let c;if(state.view==='dashboard'){let challenges=[];try{const cd=await api('/api/challenges');challenges=cd.challenges||[]}catch(e){console.error(e)}c=`<div class=hero><h1>أهلاً ${esc(u.name)} 👋</h1><p>كل مهمة مكتملة ترفع رصيدك وتزيد XP وتقرّبك من مستوى أعلى. اختر المهمة بعد معرفة تفاصيلها كاملة.</p><button class=btn onclick="go('tasks')">استكشف المهام</button></div><div class=grid><div class="card metric"><span class=icon>🎁</span><span class=kpi>Points</span><strong>${fmt(u.points)}</strong></div><div class="card metric"><span class=icon>💰</span><span class=kpi>Cash</span><strong>${fmt(u.cash)}</strong></div><div class="card metric"><span class=icon>⚡</span><span class=kpi>XP</span><strong>${fmt(u.xp)}</strong></div><div class="card metric"><span class=icon>◆</span><span class=kpi>الباقة</span><strong style="font-size:22px">${esc(u.package||'Free')}</strong></div></div><div class=section>${levelBlock(u)}</div><div class="grid2 section"><div class=card><div class=space><div><h2>تقدمك</h2><p class=muted>المستوى مستقل عن الباقة.</p></div><button class="btn secondary" onclick="go('profile')">تفاصيل الحساب</button></div><div class=grid2 style="margin-top:15px"><div><small class=muted>المهام</small><h3>اكتشف الجديدة</h3></div><div><small class=muted>المكافآت</small><h3>استبدل نقاطك</h3></div></div></div><div class=card><div class=space><div><h2>الباقة الحالية</h2><p class=muted>الوصول والحدود حسب الباقة.</p></div><span class=pill>${esc(u.package||'Free')}</span></div><button class="btn" onclick="go('packages')">عرض الباقات</button></div></div>`}else if(state.view==='tasks')c=await tasksPage();else if(state.view==='packages')c=packagesPage();else if(state.view==='rewards')c=await rewardsPage();else if(state.view==='wallet')c=walletPage();else if(state.view==='referrals')c=await referralsPage();else if(state.view==='notifications')c=await notificationsPage();else if(state.view==='support')c=await supportPage();else if(state.view==='fairplay')c=fairPlayPage();else c=profilePage();layout(c)}
async function tasksPage(){const d=await api('/api/tasks');const mainTasks=d.tasks.filter(t=>!t.isAdditional);const cats=['all',...new Set(mainTasks.map(t=>t.category||t.type))];return `<div class=space><div><h1>المهام</h1><p class=subtitle>لا تبدأ أي مهمة قبل قراءة تفاصيلها ومتطلباتها.</p></div><span class=pill blue>${mainTasks.length} مهمة متاحة</span></div><div class=categoryTabs>${cats.map(x=>`<button class="btn ${state.taskFilter===x?'':'secondary'}" onclick="state.taskFilter='${esc(x)}';render()">${x==='all'?'الكل':esc(x)}</button>`).join('')}</div><div class="grid2 section">${mainTasks.filter(t=>state.taskFilter==='all'||(t.category||t.type)===state.taskFilter).map(t=>taskCard(t)).join('')}</div>`}function taskCard(t){return `<div class="card taskCard"><div class=space><span class=pill>${esc(t.category||t.type)}</span><span class="pill ${t.eligibility?'gold':'green'}"><span class="statusDot ${t.eligibility?'gold':'green'}"></span>${t.eligibility?'غير مؤهل':'مؤهل'}</span></div><h2 style="margin-top:13px">${esc(t.title)}</h2><p class=muted>${esc(t.description||'مهمة متاحة ضمن Tasko.')}</p><div class=taskMeta><span class=reward>${fmt(t.points)} Points</span><span class=pill>+${fmt(t.xp)} XP</span><span class=pill>~${Math.ceil((t.duration||60)/60)} دقيقة</span></div><div class=space><small class=muted>الباقة: ${esc(t.packageMin||t.package||'Free')} · المستوى: ${levelLabel(t)}+</small><button class="btn ${t.eligibility?'ghost':''}" ${t.eligibility?'disabled':''} onclick='openTask(${JSON.stringify(t)})'>التفاصيل</button></div></div>`}
function openTask(t){const modal=document.createElement('div');modal.className='modalBack';modal.id='taskModal';const levelReq={name:levelLabel(t)};modal.innerHTML=`<div class=modal><div class=space><div><span class=pill>${esc(t.category||t.type)}</span><h2 style="margin-top:10px">${esc(t.title)}</h2></div><button class="btn ghost" onclick="$('#taskModal').remove()">إغلاق</button></div><p class=subtitle>${esc(t.description||'هذه المهمة لا تحتوي على وصف إضافي.')}</p><div class=detailList><div class=detailItem><small>المكافأة</small><b>${fmt(t.points)} Points</b></div><div class=detailItem><small>XP</small><b>+${fmt(t.xp)} XP</b></div><div class=detailItem><small>المدة المتوقعة</small><b>حوالي ${Math.ceil((t.duration||60)/60)} دقيقة</b></div><div class=detailItem><small>التحقق</small><b>${t.verify||t.verification||'مراجعة'}</b></div><div class=detailItem><small>أقل مستوى</small><b>${levelReq.name}</b></div><div class=detailItem><small>أقل باقة</small><b>${esc(t.packageMin||t.package||'Free')}</b></div><div class=detailItem><small>حد التكرار</small><b>${fmt(t.repeatLimit||t.dailyLimit||1)} مرة</b></div><div class=detailItem><small>التتبع</small><b>${esc(t.tracking||'داخلي')}</b></div></div><div class="notice section"><b>قبل البدء:</b> اقرأ المتطلبات كاملة، وتأكد أن لديك الوقت والبيانات اللازمة. بعد بدء المهمة يتم تسجيل محاولة جديدة.</div><div class=row style="justify-content:flex-start;margin-top:18px"><button class=btn onclick="startTask('${esc(t.id)}')">ابدأ المهمة</button><button class="btn ghost" onclick="$('#taskModal').remove()">لا أريد البدء</button></div></div>`;document.body.appendChild(modal)}
async function startTask(id){try{const d=await api('/api/task/start',{method:'POST',body:JSON.stringify({taskId:id})});$('#taskModal')?.remove();openAttempt(d.attempt,d.task)}catch(e){toast(e.message)}}function openAttempt(a,t){const m=document.createElement('div');m.className='modalBack';m.id='attemptModal';let secs=Number(t.duration||60),left=secs;function draw(){m.innerHTML=`<div class=modal><span class=pill blue>المهمة قيد التنفيذ</span><h2 style="margin-top:12px">${esc(t.title)}</h2><div class=card style="background:#f8fafc;text-align:center;margin:16px 0"><div class=muted>الوقت المتبقي للمحاكاة</div><div id=timer style="font-size:42px;font-weight:800;margin-top:5px">${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}</div></div><p class=muted>أكمل الخطوات المطلوبة للمهمة. عند الانتهاء اضغط إرسال للتحقق.</p><button class=btn style="width:100%" onclick="submitAttempt('${a.id}')">إتمام وإرسال المهمة</button></div>`}draw();document.body.appendChild(m);const timer=setInterval(()=>{left=Math.max(0,left-1);const e=$('#timer');if(e)e.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(left===0)clearInterval(timer)},1000)}async function submitAttempt(id){try{await api('/api/task/submit',{method:'POST',body:JSON.stringify({attemptId:id})});$('#attemptModal')?.remove();toast('تم إرسال المهمة. إذا كانت تحتاج مراجعة ستظهر Pending.');render()}catch(e){toast(e.message)}}
function packagesPage(){const current=state.user.package||'Free';return `<h1>الباقات</h1><p class=subtitle>الباقات خدمة وصول وميزات، وليست استثماراً ولا تتضمن وعداً بعائد. تفاصيل المزايا النهائية والأسعار يمكن تحديدها من Owner Control Center لاحقاً.</p><div class=grid3><div class="card package ${current==='Free'?'current':''}"><span class="tag pill blue">${current==='Free'?'الحالية':'Free'}</span><h2>Free</h2><p>الخطة الأساسية</p><div class=notice>مزايا هذه الباقة قيد الإعداد النهائي.</div><button class="btn ghost" disabled>${current==='Free'?'الحالية':'الأساسية'}</button></div><div class="card package plus ${current==='Plus'?'current':''}"><span class="tag pill">Plus</span><h2>Plus</h2><p>وصول ومزايا إضافية</p><div class=notice>سنحدد المزايا والحدود النهائية قبل الإطلاق.</div><button class=btn onclick="changePackage('Plus')">${current==='Plus'?'الباقة الحالية':'تجربة التفعيل'}</button></div><div class="card package premium ${current==='Premium'?'current':''}"><span class="tag pill" style="background:#fff;color:#111">Premium</span><h2>Premium</h2><p>أعلى مستوى وصول وأولوية</p><div class=notice style="background:#ffffff12;border-color:#ffffff22;color:#dfe8f3">المزايا النهائية ستحدد لاحقاً من لوحة المالك.</div><button class="btn ghost" onclick="changePackage('Premium')">${current==='Premium'?'الباقة الحالية':'تفعيل تجريبي'}</button></div></div><div class=card section><h3>بعد التفعيل</h3><p class=muted>في النموذج الحالي، عند تغيير الباقة يتم تحديث الحساب وإعادة رسم الموقع فوراً. Premium يفعّل الهوية الداكنة مباشرة.</p></div>`}async function changePackage(p){try{state.user=(await api('/api/packages/change',{method:'POST',body:JSON.stringify({package:p})})).user;toast('تم تحديث الباقة — وتم تطبيق الثيم فوراً');render()}catch(e){toast(e.message)}}
async function rewardsPage(){const d=await api('/api/rewards');const cats=['all',...new Set(d.offers.flatMap(o=>[o.category||'شركاء',o.redemptionType||'عرض',o.partner||'شركاء']))];return `<div class=space><div><h1>متجر المكافآت</h1><p class=subtitle>الاسترداد يعتمد على <b>النقاط + المستوى</b>، وليس النقاط وحدها.</p></div><span class=pill blue>${fmt(state.user.points)} Points</span></div><div class=categoryTabs>${cats.map(x=>`<button class="btn ${state.rewardCategory===x?'':'secondary'}" onclick="state.rewardCategory='${esc(x)}';render()">${esc(x==='all'?'الكل':x)}</button>`).join('')}</div><div class="grid2 section">${d.offers.filter(o=>state.rewardCategory==='all'||(o.partner||'شركاء')===state.rewardCategory||(o.category||'شركاء')===state.rewardCategory||(o.redemptionType||'عرض')===state.rewardCategory).map(o=>`<div class=card><div class=space><span class=pill>${esc(o.partner||'شريك')}</span><span class="pill ${o.eligible?'green':'gold'}">${o.eligible?'متاح':'المستوى غير كافٍ'}</span></div><h2 style="margin-top:12px">${esc(o.title)}</h2><p class=muted>${esc(o.description)}</p><div class=taskMeta><span class=reward>${fmt(o.pointsCost)} Points</span><span class=pill>${levelLabel(o)}+</span><span class=pill>${esc(o.packageMin||'Free')}+</span></div><button class=btn ${o.eligible?'':'ghost'} ${o.eligible?'':'disabled'} onclick="redeem('${esc(o.id)}')">استبدال</button></div>`).join('')||'<div class=card empty>لا توجد مكافآت في هذه الفئة حالياً.</div>'}</div><div class=section><h2>سجل الاسترداد</h2><div class=tableWrap><table class=table><tr><th>المرجع</th><th>الشريك</th><th>النقاط</th><th>الحالة</th><th>التاريخ</th></tr>${d.history.map(r=>`<tr><td>${esc(r.code||r.id)}</td><td>${esc(r.partnerId)}</td><td>${fmt(r.points)}</td><td><span class=pill green>${esc(r.status)}</span></td><td>${date(r.at)}</td></tr>`).join('')||'<tr><td colspan=5 class=empty>لا يوجد سجل بعد.</td></tr>'}</table></div></div>`}async function redeem(id){try{const d=await api('/api/redeem',{method:'POST',body:JSON.stringify({offerId:id})});state.user=d.user;toast('تم إصدار رمز الاسترداد: '+d.redemption.code);render()}catch(e){toast(e.message)}}
function walletPage(){return `<h1>المحفظة</h1><p class=subtitle>افصل دائماً بين Points وCash. السحب يخضع للمراجعة قبل الاعتماد.</p><div class=grid><div class="card metric"><span class=kpi>النقاط</span><strong>${fmt(state.user.points)}</strong></div><div class="card metric"><span class=kpi>الرصيد النقدي</span><strong>${fmt(state.user.cash)}</strong></div></div><div class="grid2 section"><div class=card><h2>طلب سحب</h2><p class=muted>الحد الأدنى الحالي يتم التحكم به من لوحة المالك.</p><div class=field><label>المبلغ</label><input id=wa class=input type=number min=0></div><div class=field><label>طريقة السحب</label><select id=wm class=input onchange="toggleWithdrawalFields()"><option value=cliq>CliQ</option><option value=bank>تحويل بنكي</option></select></div><div class=field><label>اسم المستفيد</label><input id=wrn class=input></div><div class=field id=cliqField><label>CliQ / رقم الهاتف / المعرف</label><input id=wri class=input></div><div class=field id=bankField style="display:none"><label>اسم البنك</label><input id=wb class=input><label style="display:block;margin-top:8px">رقم الحساب / IBAN</label><input id=wba class=input></div><button class=btn onclick="withdraw()">إرسال طلب السحب</button></div><div class=card><h2>سجل السحب</h2><div id=wUser><div class=empty>جارٍ فحص سجل السحب...</div></div></div></div>`}function toggleWithdrawalFields(){const bank=$('#wm')?.value==='bank';if($('#cliqField'))$('#cliqField').style.display=bank?'none':'block';if($('#bankField'))$('#bankField').style.display=bank?'block':'none'}
async function withdraw(){try{const d=await api('/api/withdraw',{method:'POST',body:JSON.stringify({amount:$('#wa').value,method:$('#wm').value,recipientName:$('#wrn').value,recipientIdentifier:$('#wri').value,bankName:$('#wb').value,bankAccount:$('#wba').value})});state.user=d.user;toast('تم إرسال طلب السحب للمراجعة');render()}catch(e){toast(e.message)}}async function loadUserWithdrawals(){const e=$('#wUser');if(!e)return;try{const d=await api('/api/user/dashboard');const items=d.withdrawals||[];e.innerHTML=items.length?items.map(w=>`<div class=detailItem style="margin:8px 0"><b>${fmt(w.amount)}</b><span class=pill>${esc(w.status)}</span><small>${date(w.createdAt)}</small></div>`).join(''):'<div class=empty>لا يوجد سجل سحب حتى الآن.</div>'}catch(err){e.innerHTML='<div class=empty>تعذر تحميل سجل السحب حالياً. حاول تحديث الصفحة.</div>';}}
async function referralsPage(){const d=await api('/api/referrals');return `<h1>الإحالات</h1><p class=subtitle>مكافأة المُحيل لا تُصرف عند التسجيل فقط؛ تتأهل الإحالة بعد أول مهمة حقيقية معتمدة.</p><div class=grid2><div class=card><h2>كودك</h2><div style="font-size:26px;font-weight:800;margin:12px 0">${esc(d.code)}</div><div class=notice>${location.origin}${esc(d.link)}</div><button class=btn style="margin-top:12px" onclick="navigator.clipboard?.writeText('${location.origin}${d.link}');toast('تم نسخ الرابط')">نسخ الرابط</button></div><div class=card><h2>سجل الإحالات</h2>${d.items.map(r=>`<div class=detailItem style="margin:8px 0"><b>${esc(r.status)}</b><small>${date(r.createdAt)}</small></div>`).join('')||'<div class=empty>لا توجد إحالات بعد.</div>'}</div></div>`}async function notificationsPage(){const d=await api('/api/notifications');return `<h1>الإشعارات</h1><p class=subtitle>${fmt(d.unread)} غير مقروء</p>${d.items.map(n=>`<div class=card style="margin:10px 0"><div class=space><h3>${esc(n.title)}</h3><span class=pill>${esc(n.type||'info')}</span></div><p>${esc(n.message)}</p><small class=muted>${date(n.at)}</small></div>`).join('')||'<div class=card empty>لا توجد إشعارات.</div>'}`}
async function supportPage(){const d=await api('/api/tickets');return `<h1>الدعم</h1><p class=subtitle>افتح تذكرة وسيظهر لك سجل المحادثة والحالة.</p><div class=grid2><div class=card><h2>فتح تذكرة</h2><div class=field><label>الموضوع</label><input id=ts class=input></div><div class=field><label>الرسالة</label><textarea id=tm class=input rows=5></textarea></div><button class=btn onclick="ticket()">إرسال</button></div><div><h2>تذاكرك</h2>${d.tickets.map(t=>`<div class=card style="margin:10px 0"><div class=space><b>${esc(t.subject)}</b><span class=pill>${esc(t.status)}</span></div><p>${t.messages.map(m=>esc(m.text)).join('<br>')}</p><small class=muted>${date(t.createdAt)}</small></div>`).join('')||'<div class=card empty>لا توجد تذاكر.</div>'}</div></div>`}async function ticket(){try{await api('/api/ticket',{method:'POST',body:JSON.stringify({subject:$('#ts').value,message:$('#tm').value})});toast('تم فتح التذكرة');render()}catch(e){toast(e.message)}}function fairPlayPage(){return `<h1>Fair Play & Trust</h1><p class=subtitle>قواعد واضحة لحماية المستخدمين والمعلنين والمنصة.</p><div class=grid2><div class=card><h2>المسموح</h2><p>إنجاز المهام بالطريقة المطلوبة، إدخال بيانات صحيحة، استخدام حسابك الشخصي، والالتزام بشروط كل مهمة.</p><h2 style="margin-top:20px">الممنوع</h2><p>تعدد الحسابات، مشاركة الحساب، التلاعب بالتتبع، الإحالات الوهمية، تكرار المكافآت، استغلال الثغرات، البيانات المزيفة، أو الأتمتة غير المصرح بها.</p></div><div class=card><h2>ماذا يحدث عند المخالفة؟</h2><ol style="line-height:2.1"><li>تنبيه عند المخالفات البسيطة.</li><li>تقييد بعض الوظائف عند التكرار.</li><li>تعليق مؤقت في الحالات الأشد.</li><li>حظر في الحالات الخطيرة أو المتكررة.</li></ol><div class=warning notice>يمكن للمستخدم طلب مراجعة/اعتراض على التقييد. القرارات تُسجل في سجل تدقيق داخلي.</div></div></div><div class=card section><h2>الخصوصية والثقة</h2><p>يجب أن يكون جمع البيانات واستخدامها وفق سياسة الخصوصية وشروط الخدمة، مع حماية الحسابات والعمليات المالية ومراجعة أي تكاملات خارجية قبل الإطلاق الحقيقي.</p></div>`}
function profilePage(){const u=state.user,l=levelInfo(u.xp),pct=l.next?Math.min(100,Math.max(0,(u.xp-l.min)/(l.next-l.min)*100)):100;return `<h1>الملف الشخصي</h1><p class=subtitle>إدارة معلومات الحساب، المستوى، الباقة والأمان من مكان واحد.</p><div class=grid2><div class=card><div class=space><div><h2>بيانات الحساب</h2><p class=muted>المعلومات الأساسية</p></div><span class=pill green><span class="statusDot green"></span>${esc(u.accountState||'Normal')}</span></div><div class=detailList style="margin-top:15px"><div class=detailItem><small>الاسم</small><b>${esc(u.name)}</b></div><div class=detailItem><small>البريد الإلكتروني</small><b>${esc(u.email)}</b></div><div class=detailItem><small>رقم الهاتف</small><b>${esc(u.phone||'—')}</b></div><div class=detailItem><small>تاريخ إنشاء الحساب</small><b>${date(u.createdAt)}</b></div><div class=detailItem><small>الباقة الحالية</small><b>${esc(u.package||'Free')}</b></div><div class=detailItem><small>الحالة</small><b>${esc(u.accountState||'Normal')}</b></div></div></div><div class=card><div class=space><div><h2>المستوى</h2><p class=muted>تقدم XP مستقل عن الباقة.</p></div><span class=levelBadge style="--level:${l.cls==='bronze'?'#b77942':l.cls==='silver'?'#718096':l.cls==='gold'?'#c89420':'#4c8fd8'}">${l.name}</span></div><div class=progress style="margin-top:18px"><span style="width:${pct}%"></span></div><div class=space style="margin-top:9px"><b>${fmt(u.xp)} XP</b><small class=muted>${l.next?fmt(l.next-u.xp)+' XP للمستوى التالي':'أعلى مستوى'}</small></div><div class=grid2 style="margin-top:16px"><div class=detailItem><small>المستوى الحالي</small><b>${l.name}</b></div><div class=detailItem><small>الباقة</small><b>${esc(u.package||'Free')}</b></div></div></div></div><div class="grid2 section"><div class=card><h2>إحصائيات الحساب</h2><div class=grid2 style="margin-top:14px"><div class=detailItem><small>Points</small><b>${fmt(u.points)}</b></div><div class=detailItem><small>Cash</small><b>${fmt(u.cash)}</b></div><div class=detailItem><small>XP</small><b>${fmt(u.xp)}</b></div><div class=detailItem><small>الباقة</small><b>${esc(u.package||'Free')}</b></div></div></div><div class=card><h2>الأمان</h2><div class=field><label>كلمة المرور الحالية</label><input id=cur class=input type=password>${eye('cur')}</div><div class=field style="position:relative"><label>كلمة المرور الجديدة</label><input id=np class=input type=password oninput="profilePwCheck()">${eye('np')}</div><div id=profilePw style="font-size:12px"></div><button class=btn onclick="changePw()">تحديث كلمة المرور</button></div></div>`}function profilePwCheck(){const p=$('#np')?.value||'';$('#profilePw').innerHTML=[['8+',p.length>=8],['A-Z',/[A-Z]/.test(p)],['a-z',/[a-z]/.test(p)],['0-9',/\d/.test(p)],['رمز',/[^A-Za-z0-9]/.test(p)]].map(x=>`<span class="pill ${x[1]?'green':''}">${x[0]}</span>`).join(' ')}async function changePw(){try{await api('/api/profile/password',{method:'POST',body:JSON.stringify({currentPassword:$('#cur').value,newPassword:$('#np').value})});toast('تم تغيير كلمة المرور');render()}catch(e){toast(e.message)}}
// ADMIN
function adminRender(){let c;if(state.view==='dashboard')c=adminDashboard();else if(state.view==='users')c=usersPage();else if(state.view==='admins')c=adminsPage();else if(state.view==='advertisers')c=adminAdvertisers();else if(state.view==='campaigns')c=campaignsPage();else if(state.view==='tasks')c=adminTasks();else if(state.view==='withdrawals')c=withdrawalsPage();else if(state.view==='support')c=adminSupport();else if(state.view==='fraud')c=fraudPage();else if(state.view==='reports')c=reportsPage();else if(state.view==='activities')c=activitiesPage();else if(state.view==='audit')c=auditPage();else if(state.view==='settings')c=settingsPage();else if(state.view==='packagesAdmin')c=packagesAdminPage();else if(state.view==='rewardsAdmin')c=rewardsAdminPage();else if(state.view==='sandbox')c=sandboxPage();else c=previewPage();layout(c)}function adminDashboard(){return `<div class=hero><h1>Owner Control Center</h1><p>نظرة تشغيلية سريعة. التفاصيل الكاملة موجودة في التقارير والتحليلات.</p><button class=btn onclick="go('reports')">فتح التقارير الكاملة</button></div><div id=summaryBox class=grid2>جارٍ التحميل...</div>`}async function loadSummary(){const d=await api('/api/admin/summary');const map=[['users','المستخدمون','👥'],['advertisers','المعلنون','📣'],['pendingTasks','مهام قيد المراجعة','⏳'],['pendingWithdrawals','سحوبات قيد المراجعة','💳'],['tickets','تذاكر مفتوحة','💬'],['campaigns','الحملات','📊'],['revenue','إيرادات المنصة','💰']];$('#summaryBox').innerHTML=map.map(x=>`<div class=card metric><span class=icon>${x[2]}</span><span class=kpi>${x[1]}</span><strong>${fmt(d[x[0]])}</strong></div>`).join('')}
function usersPage(){return `<h1>المستخدمون</h1><p class=subtitle>هذه الصفحة للمستخدمين فقط. Owner/Admin والمعلنون منفصلون تماماً.</p><div class=card><div class=searchRow><input id=uq class=input placeholder="بحث بالاسم أو البريد أو الهاتف" oninput="loadUsers()"><select id=us class=input onchange="loadUsers()"><option value="">كل الحالات</option><option>Normal</option><option>Limited</option><option>Suspended</option><option>Banned</option></select><select id=up class=input onchange="loadUsers()"><option value="">كل الباقات</option><option>Free</option><option>Plus</option><option>Premium</option></select><button class="btn secondary" onclick="loadUsers()">تحديث</button></div></div><div id=usersBox class=section>جارٍ التحميل...</div>`}async function loadUsers(){const q=$('#uq')?.value||'',s=$('#us')?.value||'';const d=await api('/api/admin/users?q='+encodeURIComponent(q)+'&state='+encodeURIComponent(s));let xs=d.users;if($('#up')?.value)xs=xs.filter(u=>u.package===$('#up').value);$('#usersBox').innerHTML=`<div class=card><div class=space><h2>النتائج</h2><span class=pill>${xs.length} مستخدم</span></div><div class=tableWrap style="margin-top:13px"><table class=table><tr><th>المستخدم</th><th>الحالة</th><th>المستوى</th><th>الباقة</th><th>Points</th><th>XP</th><th>الإنشاء</th></tr>${xs.map(u=>`<tr><td><b>${esc(u.name)}</b><br><small class=muted>${esc(u.email)}<br>${esc(u.phone||'')}</small></td><td><span class=pill>${esc(u.accountState)}</span></td><td>${esc(u.level?.name||levelInfo(u.xp).name)}</td><td>${esc(u.package||'Free')}</td><td>${fmt(u.points)}</td><td>${fmt(u.xp)}</td><td>${date(u.createdAt)}</td></tr>`).join('')||'<tr><td colspan=7 class=empty>لا نتائج.</td></tr>'}</table></div></div>`}
function adminsPage(){return `<h1>إدارة الأدمن</h1><p class=subtitle>Owner يحدد الصلاحيات مباشرة. الأدمن لا يستطيع رفع صلاحيات نفسه.</p><div class=grid2><div class=card><h2>إضافة Admin</h2><div class=field><label>الاسم</label><input id=adn class=input></div><div class=field><label>البريد</label><input id=ade class=input type=email></div><div class=field><label>كلمة المرور</label><input id=adp class=input type=password></div><div class=field><label>الصلاحيات</label><div id=perms></div></div><button class=btn onclick="createAdmin()">إنشاء Admin</button></div><div id=adminsBox class=card>جارٍ التحميل...</div></div>`}async function loadPerms(){const ps=['users','tasks','campaigns','partners','withdrawals','rewards','referrals','subscriptions','fraud','support','reports','audit','settings','sandbox','admins','advertisers','preview'];$('#perms').innerHTML=ps.map(p=>`<label style="display:block;margin:7px 0"><input type=checkbox value="${p}"> ${p}</label>`).join('')}async function loadAdmins(){const d=await api('/api/admin/admins');$('#adminsBox').innerHTML=`<h2>الحسابات الإدارية</h2><div class=detailItem style="margin:10px 0"><b>Owner</b><small>${esc(d.owner?.email||'')}</small><span class=pill green>Full Access</span></div>${d.admins.map(a=>`<div class=detailItem style="margin:10px 0"><b>${esc(a.name)}</b><small>${esc(a.email)}</small><div class=taskMeta>${a.permissions.map(p=>`<span class=pill>${p}</span>`).join('')}</div><span class=pill>${esc(a.accountState)}</span></div>`).join('')}`};async function createAdmin(){const permissions=[...document.querySelectorAll('#perms input:checked')].map(x=>x.value);const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/admins',{method:'POST',body:JSON.stringify({name:$('#adn').value,email:$('#ade').value,password:$('#adp').value,permissions,confirm})});toast('تم إنشاء الأدمن');render()}catch(e){toast(e.message)}}
function adminAdvertisers(){return `<h1>المعلنون</h1><p class=subtitle>حسابات الشركات منفصلة عن المستخدمين والأدمن.</p><div class=grid2><div class=card><h2>إنشاء معلن</h2><div class=field><label>الشركة</label><input id=ac class=input></div><div class=field><label>جهة الاتصال</label><input id=acn class=input></div><div class=field><label>البريد</label><input id=ace class=input type=email></div><div class=field><label>كلمة المرور</label><input id=acp class=input type=password></div><label><input id=vip type=checkbox> VIP Advertiser</label><button class=btn style="margin-top:12px" onclick="createAdv()">إنشاء الحساب</button></div><div id=advBox>جارٍ التحميل...</div></div>`}async function createAdv(){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/advertisers',{method:'POST',body:JSON.stringify({company:$('#ac').value,contact:$('#acn').value,email:$('#ace').value,password:$('#acp').value,vip:$('#vip').checked,confirm})});toast('تم إنشاء المعلن');render()}catch(e){toast(e.message)}}async function loadAdv(){const d=await api('/api/admin/advertisers');$('#advBox').innerHTML=d.advertisers.map(a=>`<div class=card style="margin:10px 0"><div class=space><h3>${esc(a.company)}</h3><span class="pill ${a.vip?'gold':'blue'}">${a.vip?'VIP':'Regular'}</span></div><p>${esc(a.email)} · ${esc(a.status)}</p><small class=muted>${date(a.verifiedAt)}</small></div>`).join('')||'<div class=card empty>لا يوجد معلنون.</div>'}
function rewardsAdminPage(){return `<h1>إدارة المكافآت</h1><p class=subtitle>Owner يقدر ينشئ ويعدل ويوقف ويحذف عروض متجر المكافآت. كل تعديل حساس يحتاج كود التأكيد الثاني.</p><div class=card><h2>إضافة مكافأة</h2><div class=grid2><div class=field><label>اسم المكافأة</label><input id=rn class=input placeholder=مثال: خصم 10%></div><div class=field><label>الوصف</label><input id=rd class=input></div><div class=field><label>الشريك</label><select id=rp class=input></select></div><div class=field><label>النقاط المطلوبة</label><input id=rc class=input type=number min=0 value=500></div><div class=field><label>الحد الأدنى للمستوى</label><input id=rl class=input type=number min=0 value=0></div><div class=field><label>الباقة المطلوبة</label><select id=rpg class=input><option>Free</option><option>Plus</option><option>Premium</option></select></div><div class=field><label>عدد مرات الاستخدام لكل مستخدم</label><input id=ru class=input type=number min=1 value=1></div><div class=field><label>نوع الاسترداد</label><select id=rt class=input><option value=code>Code</option><option value=qr>QR</option><option value=manual>Manual</option></select></div></div><label style=display:block;margin:10px 0><input id=ra type=checkbox checked> مفعلة</label><button class=btn onclick=addReward()>إضافة المكافأة</button></div><div id=rewardsAdminBox class=section>جارٍ تحميل المكافآت...</div>`}
async function loadRewardsAdmin(){const e=$('#rewardsAdminBox');if(!e)return;try{const d=await api('/api/admin/rewards');$('#rp').innerHTML='<option value="">بدون شريك</option>'+d.partners.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');e.innerHTML=d.offers.map(o=>`<div class=card style="margin:10px 0"><div class=space><div><h2>${esc(o.title)}</h2><small class=muted>${esc(o.partner||'بدون شريك')} · ${fmt(o.pointsCost)} Points · ${levelLabel(o)}+</small></div><span class="pill ${o.active?'green':'red'}">${o.active?'مفعلة':'موقوفة'}</span></div><p>${esc(o.description||'')}</p><div class=taskMeta><span class=pill>الباقة: ${esc(o.packageMin||'Free')}</span><span class=pill>الاستخدام: ${fmt(o.usesPerUser||1)}</span><span class=pill>${esc(o.redemptionType||'code')}</span></div><div class=row style="margin-top:10px"><button class="btn secondary" onclick='editReward(${JSON.stringify(o)})'>تعديل</button><button class="btn ${o.active?'danger':'secondary'}" onclick="toggleReward('${esc(o.id)}',${!o.active})">${o.active?'إيقاف':'تفعيل'}</button><button class="btn danger" onclick="deleteReward('${esc(o.id)}')">حذف</button></div></div>`).join('')||'<div class=card empty>لا توجد مكافآت.</div>'}catch(err){e.innerHTML='<div class=card empty>تعذر تحميل المكافآت.</div>';toast(err.message)}}
function editReward(o){const title=prompt('اسم المكافأة',o.title);if(title===null)return;const description=prompt('الوصف',o.description||'');if(description===null)return;const points=prompt('النقاط المطلوبة',o.pointsCost);if(points===null)return;const levelMin=prompt('الحد الأدنى للمستوى',o.levelMin||0);if(levelMin===null)return;const packageMin=prompt('الباقة المطلوبة: Free / Plus / Premium',o.packageMin||'Free');if(packageMin===null)return;const uses=prompt('عدد الاستخدامات لكل مستخدم',o.usesPerUser||1);if(uses===null)return;const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;api('/api/admin/rewards/update',{method:'POST',body:JSON.stringify({id:o.id,title,description,pointsCost:Number(points),levelMin:Number(levelMin),packageMin,usesPerUser:Number(uses),confirm})}).then(()=>{toast('تم تعديل المكافأة');render()}).catch(e=>toast(e.message))}
async function addReward(){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/rewards',{method:'POST',body:JSON.stringify({title:$('#rn').value,description:$('#rd').value,partnerId:$('#rp').value,pointsCost:Number($('#rc').value)||0,levelMin:Number($('#rl').value)||0,packageMin:$('#rpg').value,usesPerUser:Number($('#ru').value)||1,redemptionType:$('#rt').value,active:$('#ra').checked,confirm})});toast('تمت إضافة المكافأة');render()}catch(e){toast(e.message)}}
async function toggleReward(id,active){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/rewards/update',{method:'POST',body:JSON.stringify({id,active,confirm})});toast(active?'تم تفعيل المكافأة':'تم إيقاف المكافأة');render()}catch(e){toast(e.message)}}
async function deleteReward(id){if(!confirm('حذف المكافأة نهائياً؟'))return;const code=prompt('رمز التأكيد الأمني من 4 أرقام');if(code===null)return;try{await api('/api/admin/rewards/delete',{method:'POST',body:JSON.stringify({id,confirm:code})});toast('تم حذف المكافأة');render()}catch(e){toast(e.message)}}
function campaignsPage(){return `<h1>الحملات</h1><p class=subtitle>اربط كل حملة بمعلن محدد، وتابع الميزانية والنقرات والتحويلات والحالة.</p><div class=card><div class=grid2><input id=cn class=input placeholder="اسم الحملة"><input id=cb class=input type=number placeholder="الميزانية"><select id=ca class=input><option value="">بدون معلن</option></select><select id=co class=input><option value="conversion">Conversion</option><option value="lead">Lead</option><option value="traffic">Traffic</option></select></div><button class=btn style="margin-top:12px" onclick="createCampaign()">إنشاء الحملة</button></div><div id=campBox class=section>جارٍ التحميل...</div>`}async function loadAdvSelect(){const d=await api('/api/admin/advertisers');$('#ca').innerHTML='<option value="">بدون معلن</option>'+d.advertisers.map(a=>`<option value="${a.id}">${esc(a.company)}</option>`).join('')}async function createCampaign(){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/campaigns',{method:'POST',body:JSON.stringify({name:$('#cn').value,budget:$('#cb').value,advertiserId:$('#ca').value,objective:$('#co').value,confirm})});toast('تم إنشاء الحملة');render()}catch(e){toast(e.message)}}async function loadCampaigns(){const d=await api('/api/admin/campaigns');$('#campBox').innerHTML=d.campaigns.map(c=>`<div class=card style="margin:10px 0"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.referenceId)} · ${esc(c.advertiser?.company||'غير مسند')}</small></div><span class=pill>${esc(c.status)}</span></div><div class=grid3 style="margin-top:14px"><div class=reportStat><small>Budget</small><strong>${fmt(c.budget)}</strong></div><div class=reportStat><small>Clicks</small><strong>${fmt(c.results?.clicks)}</strong></div><div class=reportStat><small>Conversions</small><strong>${fmt(c.results?.conversions)}</strong></div></div></div>`).join('')||'<div class=card empty>لا توجد حملات.</div>'}
function adminTasks(){return `<h1>المهام</h1><p class=subtitle>منشئ مهام كامل: النوع، الهدف، الدورة، فترة الظهور، المكافآت، الشروط والتحقق.</p><div class=card><div class=grid2><div class=field><label>اسم المهمة</label><input id=tn class=input placeholder=مثال : أكمل 5 مهام></div><div class=field><label>نوع المهمة</label><select id=tt class=input><option value=custom>مخصصة</option><option value=complete_tasks>إكمال عدد من المهام</option><option value=login_count>تسجيل الدخول عدد مرات</option><option value=daily_login>تسجيل الدخول يومياً</option><option value=collect_points>جمع Points</option><option value=collect_xp>جمع XP</option><option value=referrals>دعوة أصدقاء مؤهلين</option><option value=streak>Streak متواصل</option><option value=specific_task>إكمال مهمة محددة</option><option value=category_tasks>إكمال مهام من فئة</option></select></div><div class=field><label>العدد / الهدف</label><input id=ngt class=input type=number min=1 value=1></div><div class=field><label>الدورة</label><select id=nper class=input><option value=once>مرة واحدة</option><option value=daily>يومية</option><option value=weekly>أسبوعية</option><option value=monthly>شهرية</option><option value=custom>مخصصة</option></select></div><div class=field><label>تبدأ</label><input id=nst class=input type=datetime-local></div><div class=field><label>تنتهي</label><input id=nen class=input type=datetime-local></div><div class=field><label>Points</label><input id=tp class=input type=number min=0 value=100></div><div class=field><label>XP</label><input id=tx class=input type=number min=0 value=20></div><div class=field><label>مدة المهمة بالثواني</label><input id=td class=input type=number min=0 value=60></div><div class=field><label>الحد الأدنى للمستوى</label><select id=tl class=input><option value="bronze">Bronze</option><option value="silver">Silver</option><option value="gold">Gold</option><option value="diamond">Diamond</option></select></div><div class=field><label>أقل باقة</label><select id=ntp class=input><option>Free</option><option>Plus</option><option>Premium</option></select></div><div class=field><label>طريقة التحقق</label><select id=tv class=input><option>auto</option><option>pending</option><option>manual</option></select></div><div class=field><label>الفئة</label><input id=nc class=input placeholder=عام></div><div class=field><label>الحد لكل مستخدم</label><input id=ndl class=input type=number min=1 value=1></div></div><div class=field><label>وصف المهمة</label><textarea id=ndesc class=input rows=3></textarea></div><div class=field><label>الشروط / التفاصيل</label><textarea id=ncond class=input rows=3></textarea></div><label class=checkRow><input id=nadd type=checkbox> تظهر ضمن المهام الإضافية في الرئيسية</label><button class=btn style="margin-top:12px" onclick="createTask()">إضافة مهمة</button></div><div id=taskAdminBox class=section><div class=card empty>جارٍ تحميل المهام...</div></div>`}
async function createTask(){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/tasks',{method:'POST',body:JSON.stringify({title:$('#tn').value,type:$('#tt').value,goalType:$('#tt').value,goalTarget:Number($('#ngt').value)||1,period:$('#nper').value,startsAt:$('#nst').value||null,endsAt:$('#nen').value||null,points:$('#tp').value,xp:$('#tx').value,duration:$('#td').value,levelMinId:$('#tl').value,package:$('#ntp').value,verification:$('#tv').value,category:$('#nc').value||'عام',isAdditional:$('#nadd').checked,dailyLimit:$('#ndl').value,description:$('#ndesc').value,conditions:$('#ncond').value,confirm})});toast('تمت إضافة المهمة');render()}catch(e){toast(e.message)}}
async function loadAdminTasks(){const e=$('#taskAdminBox');if(!e)return;try{const d=await api('/api/admin/tasks');e.innerHTML=d.tasks.map(t=>`<div class=card style="margin:10px 0"><div class=space><div><h3>${esc(t.title)}</h3><small class=muted>${esc(t.category||'عام')} · ${esc(t.period||'once')} · ${t.startsAt?date(t.startsAt):'بدون بداية'} → ${t.endsAt?date(t.endsAt):'بدون نهاية'}</small></div><span class="pill ${t.active?'green':'red'}">${t.active?'Active':'Inactive'}</span></div><div class=taskMeta><span class=reward>${fmt(t.points)} Points</span><span class=pill>+${fmt(t.xp)} XP</span><span class=pill>${esc(t.goalType||t.type||'custom')} · ${fmt(t.goalTarget||1)}</span><span class=pill>${esc(t.package||'Free')}</span></div><div class=row style="margin-top:10px"><button class="btn ghost" onclick='editTask(${JSON.stringify(t)})'>تعديل</button><button class="btn secondary" onclick="toggleTask('${esc(t.id)}')">${t.active?'إيقاف':'تفعيل'}</button></div></div>`).join('')||'<div class=card empty>لا توجد مهام.</div>'}catch(err){e.innerHTML='<div class=card empty>تعذر تحميل المهام. حاول إعادة المحاولة.</div>'}}
function editTask(t){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:92vh;overflow:auto"><div class=space><h2>تعديل المهمة</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2><div class=field><label>الاسم</label><input id=etn class=input value="${esc(t.title)}"></div><div class=field><label>النوع</label><select id=ett class=input><option value="custom">مخصصة</option><option value="complete_tasks">إكمال عدد من المهام</option><option value="login_count">تسجيل الدخول عدد مرات</option><option value="daily_login">تسجيل الدخول يومياً</option><option value="collect_points">جمع Points</option><option value="collect_xp">جمع XP</option><option value="referrals">دعوة أصدقاء مؤهلين</option><option value="streak">Streak متواصل</option><option value="category_tasks">إكمال مهام من فئة</option></select></div><div class=field><label>الهدف</label><input id=egt class=input type=number min=1 value="${fmt(t.goalTarget||1)}"></div><div class=field><label>الدورة</label><select id=eper class=input><option>once</option><option>daily</option><option>weekly</option><option>monthly</option><option>custom</option></select></div><div class=field><label>تبدأ</label><input id=est class=input type=datetime-local value="${t.startsAt?String(t.startsAt).slice(0,16):''}"></div><div class=field><label>تنتهي</label><input id=een class=input type=datetime-local value="${t.endsAt?String(t.endsAt).slice(0,16):''}"></div><div class=field><label>Points</label><input id=etp class=input type=number min=0 value="${fmt(t.points)}"></div><div class=field><label>XP</label><input id=etx class=input type=number min=0 value="${fmt(t.xp)}"></div></div><div class=field><label>الوصف</label><textarea id=edesc class=input rows=3>${esc(t.description||'')}</textarea></div><button class=btn onclick="saveTaskEdit('${esc(t.id)}')">حفظ التعديلات</button></div>`;document.body.appendChild(m);$('#ett').value=t.goalType||t.type||'custom';$('#eper').value=t.period||'once'}
async function saveTaskEdit(id){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/tasks/update',{method:'POST',body:JSON.stringify({id,title:$('#etn').value,goalType:$('#ett').value,type:$('#ett').value,goalTarget:Number($('#egt').value)||1,period:$('#eper').value,startsAt:$('#est').value||null,endsAt:$('#een').value||null,points:Number($('#etp').value)||0,xp:Number($('#etx').value)||0,description:$('#edesc').value,confirm})});document.querySelector('.modalBack')?.remove();toast('تم تعديل المهمة');render()}catch(e){toast(e.message)}}
async function toggleTask(id){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/tasks/toggle',{method:'POST',body:JSON.stringify({id,confirm})});toast('تم تحديث حالة المهمة');render()}catch(e){toast(e.message)}}
function withdrawalsPage(){return `<h1>السحوبات</h1><p class=subtitle>كل قرار اعتماد/رفض يحتاج تأكيداً ثانوياً، وبعد المعالجة تختفي أزرار القرار.</p><div class=card><div class=searchRow><input id=wq class=input placeholder="بحث بالمرجع أو المستخدم" oninput="loadW()"><select id=ws class=input onchange="loadW()"><option value="">كل الحالات</option><option>pending</option><option>approved</option><option>rejected</option></select><div></div><button class="btn secondary" onclick="loadW()">تحديث</button></div></div><div id=wBox class=section>جارٍ التحميل...</div>`}async function loadW(){const d=await api('/api/admin/withdrawals?q='+encodeURIComponent($('#wq')?.value||'')+'&status='+encodeURIComponent($('#ws')?.value||''));$('#wBox').innerHTML=d.withdrawals.map(w=>`<div class=card style="margin:10px 0"><div class=space><div><h3>${esc(w.referenceId)}</h3><small class=muted>User: ${esc(w.userId)}</small></div><span class=pill>${esc(w.status)}</span></div><div class=grid2 style="margin-top:12px"><div class=detailItem><small>المبلغ</small><b>${fmt(w.amount)}</b></div><div class=detailItem><small>التاريخ</small><b>${date(w.createdAt)}</b></div></div>${w.status==='pending'?`<div class=row style="margin-top:12px"><button class=btn onclick="processOp('withdrawal','${esc(w.id)}','approve')">اعتماد</button><button class="btn danger" onclick="processOp('withdrawal','${esc(w.id)}','reject')">رفض</button></div>`:`<div class=notice style="margin-top:12px">تمت المعالجة بواسطة ${esc(w.processedBy||'—')} · ${esc(w.reason||'بدون سبب')}</div>`}</div>`).join('')||'<div class=card empty>لا توجد عمليات.</div>'}async function processOp(kind,id,decision){const pin=prompt('رمز التأكيد الثانوي');if(pin===null)return;const reason=prompt(decision==='reject'?'سبب الرفض (اختياري)':'ملاحظة المعالجة (اختياري)')||'';try{await api('/api/admin/verify',{method:'POST',body:JSON.stringify({kind,id,decision,confirm:pin,reason})});toast('تمت معالجة العملية');render()}catch(e){toast(e.message)}}
function adminSupport(){return `<h1>الدعم والتذاكر</h1><p class=subtitle>التذاكر، الأولوية، الرسائل، ومن تعامل معها.</p><div id=sBox>جارٍ التحميل...</div>`}async function loadSupport(){const d=await api('/api/admin/tickets');$('#sBox').innerHTML=d.tickets.map(t=>`<div class=card style="margin:10px 0"><div class=space><div><h3>${esc(t.subject)}</h3><small>${esc(t.user?.email||t.userId)}</small></div><span class=pill>${esc(t.status)}</span></div><p class=muted>الأولوية: ${esc(t.priority)} · ${date(t.createdAt)}</p><div style="border-top:1px solid var(--line);padding-top:10px">${t.messages.map(m=>`<p><b>${esc(m.by)}</b>: ${esc(m.text)}</p>`).join('')}</div><button class=btn onclick="replyTicket('${esc(t.id)}')">رد</button></div>`).join('')||'<div class=card empty>لا توجد تذاكر.</div>'}async function replyTicket(id){const m=prompt('اكتب الرد');if(!m)return;try{await api('/api/admin/ticket',{method:'POST',body:JSON.stringify({id,message:m,status:'open'})});toast('تم إرسال الرد');render()}catch(e){toast(e.message)}}function fraudPage(){return `<h1>Fraud & Violations</h1><p class=subtitle>السياسة: Normal → Limited → Suspended → Banned حسب الشدة والتكرار.</p><div class=card><div class=grid2><input id=fuid class=input placeholder="User ID"><input id=fr class=input placeholder="سبب المخالفة"><select id=fs class=input><option value="minor">Minor</option><option value="serious">Serious</option></select><button class=btn onclick="addFraud()">تسجيل المخالفة</button></div></div><div id=fBox class=section>جارٍ التحميل...</div>`}async function addFraud(){try{await api('/api/admin/fraud',{method:'POST',body:JSON.stringify({userId:$('#fuid').value,reason:$('#fr').value,severity:$('#fs').value})});toast('تم تسجيل المخالفة');render()}catch(e){toast(e.message)}}async function loadFraud(){const d=await api('/api/admin/fraud');$('#fBox').innerHTML=d.violations.map(v=>`<div class=card style="margin:9px 0"><div class=space><b>${esc(v.userId)}</b><span class="pill ${v.severity==='serious'?'red':'gold'}">${esc(v.severity)}</span></div><p>${esc(v.reason)}</p><small class=muted>${date(v.createdAt)}</small></div>`).join('')||'<div class=card empty>لا توجد مخالفات.</div>'}
function reportsPage(){return `<h1>التقارير والتحليلات</h1><p class=subtitle>هنا التفاصيل التشغيلية الكاملة. الصفحة الرئيسية تبقى مختصرة فقط.</p><div class=card><div class=searchRow><select id=rd class=input><option value=7>آخر 7 أيام</option><option value=30 selected>آخر 30 يوم</option><option value=90>آخر 90 يوم</option><option value=365>آخر سنة</option></select><button class="btn secondary" onclick="loadReports()">تحديث التقرير</button></div></div><div id=rBox class=section>جارٍ التحميل...</div>`}async function loadReports(){const days=$('#rd')?.value||30;const d=await api('/api/admin/reports?days='+days);const o=d.overview;$('#rBox').innerHTML=`<div class=grid4></div><div class=grid section><div class=card metric><span class=kpi>المستخدمون</span><strong>${fmt(o.users)}</strong><small class=muted>جدد 7 أيام: ${fmt(o.newUsers7)} · 30 يوم: ${fmt(o.newUsers30)}</small></div><div class=card metric><span class=kpi>المعلنون</span><strong>${fmt(o.advertisers)}</strong><small class=muted>نشط: ${fmt(o.activeAdvertisers)}</small></div><div class=card metric><span class=kpi>الحملات</span><strong>${fmt(o.campaigns)}</strong><small class=muted>نشطة ${fmt(o.activeCampaigns)} · Pending ${fmt(o.pendingCampaigns)} · مكتملة ${fmt(o.completedCampaigns)}</small></div><div class=card metric><span class=kpi>العمليات</span><strong>${fmt(o.taskAttempts+o.withdrawals+o.redemptions+o.transactions)}</strong><small class=muted>Transactions ${fmt(o.transactions)}</small></div></div><div class="grid2 section"><div class=card><h2>دورة المهام</h2><div class=grid2 style="margin-top:13px"><div class=reportStat><small>بدأت</small><strong>${fmt(o.startedTasks)}</strong></div><div class=reportStat><small>قيد المراجعة</small><strong>${fmt(o.pendingTasks)}</strong></div><div class=reportStat><small>مقبولة</small><strong>${fmt(o.approvedTasks)}</strong></div><div class=reportStat><small>مرفوضة</small><strong>${fmt(o.rejectedTasks)}</strong></div></div><p class=muted>Points موزعة: ${fmt(d.tasks.pointsAwarded)} · XP موزعة: ${fmt(d.tasks.xpAwarded)}</p></div><div class=card><h2>السحوبات</h2><div class=grid2 style="margin-top:13px"><div class=reportStat><small>كل الطلبات</small><strong>${fmt(o.withdrawals)}</strong></div><div class=reportStat><small>Pending</small><strong>${fmt(o.pendingWithdrawals)}</strong></div><div class=reportStat><small>مقبولة</small><strong>${fmt(o.approvedWithdrawals)}</strong></div><div class=reportStat><small>مرفوضة</small><strong>${fmt(o.rejectedWithdrawals)}</strong></div></div><p class=muted>المطلوب: ${fmt(d.withdrawals.requested)} · المعتمد: ${fmt(d.withdrawals.approved)}</p></div></div><div class="grid2 section"><div class=card><h2>الحملات والأداء</h2><div class=grid2 style="margin-top:13px"><div class=reportStat><small>Budget</small><strong>${fmt(d.campaigns.budget)}</strong></div><div class=reportStat><small>Spent</small><strong>${fmt(d.campaigns.spent)}</strong></div><div class=reportStat><small>Clicks</small><strong>${fmt(o.clicks)}</strong></div><div class=reportStat><small>Conversions</small><strong>${fmt(o.conversions)}</strong></div></div><div class=notice style="margin-top:13px">Conversion Rate: <b>${o.conversionRate}%</b></div></div><div class=card><h2>متجر المكافآت</h2><div class=grid2 style="margin-top:13px"><div class=reportStat><small>الاستردادات</small><strong>${fmt(o.redemptions)}</strong></div><div class=reportStat><small>Points مصروفة</small><strong>${fmt(d.redemptions.pointsSpent)}</strong></div></div><p class=muted>المخالفات المسجلة: ${fmt(o.violations)} · التذاكر المفتوحة: ${fmt(o.ticketsOpen)}</p></div></div><div class="grid2 section"><div class=card><h2>توزيع المستخدمين</h2><div class=taskMeta>${Object.entries(d.users.byPackage||{}).map(([k,v])=>`<span class=pill>${esc(k)}: ${fmt(v)}</span>`).join('')||'لا بيانات'}</div><div class=taskMeta>${Object.entries(d.users.byState||{}).map(([k,v])=>`<span class=pill>${esc(k)}: ${fmt(v)}</span>`).join('')}</div></div><div class=card><h2>المالية</h2><div class=grid2><div class=reportStat><small>Points داخلة</small><strong>${fmt(d.financial.pointsIn)}</strong></div><div class=reportStat><small>Points خارجة</small><strong>${fmt(d.financial.pointsOut)}</strong></div><div class=reportStat><small>Cash Flow</small><strong>${fmt(d.financial.cashFlow)}</strong></div><div class=reportStat><small>Revenue</small><strong>${fmt(o.revenue)}</strong></div></div></div></div><div class="card section"><h2>ملخص الحالات</h2><div class=tableWrap style="margin-top:12px"><table class=table><tr><th>المؤشر</th><th>القيمة</th><th>ماذا يعني</th></tr><tr><td>المستخدمون الجدد</td><td>${fmt(o.newUsers30)}</td><td>حسابات أنشئت خلال الفترة</td></tr><tr><td>العمليات قيد التنفيذ</td><td>${fmt(o.startedTasks)}</td><td>محاولات مهام بدأت ولم تُرسل بعد</td></tr><tr><td>Pending</td><td>${fmt(o.pendingTasks+o.pendingWithdrawals)}</td><td>تحتاج قرار مراجعة</td></tr><tr><td>الحملات المكتملة</td><td>${fmt(o.completedCampaigns)}</td><td>حملات وصلت إلى حالة مكتملة</td></tr><tr><td>إجمالي العمليات المالية</td><td>${fmt(d.financial.transactionCount)}</td><td>سجل المعاملات الداخلي</td></tr></table></div></div>`}
function activitiesPage(){return `<h1>سجل العمليات</h1><p class=subtitle>كل ما يحدث داخل المنصة في سجل واحد، مع بحث ونوع العملية وفترة زمنية وصفحات.</p><div class=card><div class=searchRow><input id=actq class=input placeholder="بحث بالمرجع أو المستخدم أو العملية"><select id=acttype class=input><option value="">كل العمليات</option><option value="task_attempt">محاولات المهام</option><option value="withdrawal">السحوبات</option><option value="redemption">الاستردادات</option><option value="transaction">المعاملات</option><option value="campaign">الحملات</option></select><select id=actdays class=input><option value="1">آخر يوم</option><option value="7">آخر 7 أيام</option><option value="30" selected>آخر 30 يوم</option><option value="90">آخر 90 يوم</option><option value="365">آخر سنة</option><option value="0">كل السجل</option></select><button class="btn secondary" onclick="loadActivities()">تحديث</button></div></div><div id=actBox class=section>جارٍ التحميل...</div>`}async function loadActivities(){const q=$('#actq')?.value||'',type=$('#acttype')?.value||'',days=$('#actdays')?.value||30;const d=await api('/api/admin/activities?q='+encodeURIComponent(q)+'&type='+encodeURIComponent(type)+'&days='+encodeURIComponent(days)+'&page=1&size=50');$('#actBox').innerHTML=`<div class=card><div class=space><h2>السجل</h2><span class=pill>${fmt(d.total)} عملية</span></div><div class=tableWrap style="margin-top:12px"><table class=table><tr><th>الوقت</th><th>النوع</th><th>المرجع</th><th>المستخدم/الهدف</th><th>الحالة</th><th>التفاصيل</th></tr>${d.items.map(x=>`<tr><td>${date(x.at||x.createdAt||x.startedAt)}</td><td>${esc(x.activityType||'activity')}</td><td>${esc(x.referenceId||x.id||'—')}</td><td>${esc(x.userId||x.advertiserId||x.id||'—')}</td><td>${esc(x.status||'—')}</td><td><code>${esc(JSON.stringify(x))}</code></td></tr>`).join('')||'<tr><td colspan=6 class=empty>لا توجد عمليات ضمن الفلتر الحالي.</td></tr>'}</table></div></div>`}
function auditPage(){return `<h1>سجل التدقيق</h1><p class=subtitle>سجل عمليات الإدارة مع بحث وصفحات.</p><div class=card><input id=aq class=input placeholder="ابحث في actor / action / target / metadata" oninput="loadAudit()"></div><div id=auBox class=section>جارٍ التحميل...</div>`}async function loadAudit(){const d=await api('/api/admin/audit?q='+encodeURIComponent($('#aq')?.value||'')+'&page=1&size=50');$('#auBox').innerHTML=`<div class=card><div class=space><h2>السجل</h2><span class=pill>${fmt(d.total)} عملية</span></div><div class=tableWrap style="margin-top:12px"><table class=table><tr><th>الوقت</th><th>الفاعل</th><th>الإجراء</th><th>الهدف</th><th>التفاصيل</th></tr>${d.items.map(x=>`<tr><td>${date(x.at)}</td><td>${esc(x.actorId)}</td><td>${esc(x.action)}</td><td>${esc(x.target)}</td><td><code>${esc(JSON.stringify(x.meta||{}))}</code></td></tr>`).join('')||'<tr><td colspan=5 class=empty>لا نتائج.</td></tr>'}</table></div></div>`}
function settingsPage(){return `<h1>Owner Control Center</h1><p class=subtitle>تحكم تشغيلي كامل مع تأكيد ثانوي للإجراءات الحساسة.</p><div class=grid2><div class=card><h2>الحدود والمكافآت</h2><div class=grid2>${[['minWithdrawal','Minimum withdrawal'],['referralReward','Referral reward'],['referredGift','Referred gift'],['warningLimit','Warning limit'],['tempSuspendLimit','Temp suspend limit'],['banLimit','Ban limit'],['taskDailyLimit','Daily task limit'],['pointsPerCash','Points per cash']].map(x=>`<div class=field><label>${x[1]}</label><input id=s_${x[0]} class=input type=number></div>`).join('')}</div></div><div class=card><h2>حالة المنصة والطوارئ</h2><div id=emergencyPanel>جارٍ التحميل...</div></div></div><div class=card section><div class=space><div><h2>إدارة الباقات</h2><p class=muted>كل الأسعار والحدود والمزايا والوصول.</p></div><button class=btn secondary onclick="go('packagesAdmin')">فتح صفحة الباقات</button></div></div><button class=btn style="margin-top:14px" onclick="saveSettings()">حفظ الحدود العامة</button>`}
async function loadSettings(){const d=await api('/api/admin/settings');for(const k of ['minWithdrawal','referralReward','referredGift','warningLimit','tempSuspendLimit','banLimit','taskDailyLimit','pointsPerCash'])$('#s_'+k).value=d.settings[k];renderEmergency(d.settings)}
function renderEmergency(x){$('#emergencyPanel').innerHTML=`<div class=emergencyBox><div class=space><div><b>${x.emergencyMode?'🔴 وضع الطوارئ مفعل':'🟢 الوضع الطبيعي'}</b><div class=muted>${esc(x.emergencyReason||'لا يوجد سبب')}</div></div><span class="pill ${x.emergencyMode?'red':'green'}">${x.emergencyMode?'EMERGENCY':'OPERATIONAL'}</span></div><label class=checkRow><input id=ereg type=checkbox ${x.registrationsOpen?'checked':''}> التسجيل مفتوح</label><label class=checkRow><input id=etasks type=checkbox ${x.tasksOpen?'checked':''}> المهام مفتوحة</label><label class=checkRow><input id=ewd type=checkbox ${x.withdrawalsOpen?'checked':''}> السحوبات مفتوحة</label><label class=checkRow><input id=emaint type=checkbox ${x.maintenance?'checked':''}> Maintenance</label><div class=field><label>سبب الطوارئ</label><input id=ereason class=input value="${esc(x.emergencyReason||'')}"></div><button class="btn ${x.emergencyMode?'danger':''}" onclick="saveEmergency()">تأكيد تغيير الحالة</button></div>`}
function emergencyConfirm(action,cb){root.insertAdjacentHTML('beforeend',`<div class=modalBack id=emModal><div class=modal><h2>⚠️ تأكيد إجراء حساس</h2><p class=muted>${esc(action)}</p><div class=field><label>رمز الطوارئ</label><input id=emCode class=input type=password></div><div class=row><button class="btn danger" onclick="${cb}">تأكيد وتنفيذ</button><button class="btn ghost" onclick="$('#emModal').remove()">إلغاء</button></div></div></div>`)}
function saveEmergency(){const p={registrationsOpen:$('#ereg').checked,tasksOpen:$('#etasks').checked,withdrawalsOpen:$('#ewd').checked,maintenance:$('#emaint').checked,emergencyMode:!$('#ereg').checked||!$('#etasks').checked||!$('#ewd').checked||$('#emaint').checked,reason:$('#ereason').value};emergencyConfirm('سيتم تغيير حالة خدمات المنصة. تأكد قبل التنفيذ.',`doEmergency(${JSON.stringify(p)})`)}
async function doEmergency(p){try{const d=await api('/api/admin/emergency',{method:'POST',body:JSON.stringify({...p,confirm:$('#emCode').value})});$('#emModal').remove();toast('تم تحديث حالة المنصة');renderEmergency(d.settings)}catch(e){toast(e.message)}}
function packagesAdminPage(){return `<h1>إدارة الباقات — Owner فقط</h1><p class=subtitle>كل التفاصيل التي تؤثر على الوصول والحدود والمزايا.</p><div id=pkgAdmin>جارٍ التحميل...</div>`}
async function loadPackagesAdmin(){const d=await api('/api/admin/packages');$('#pkgAdmin').innerHTML=['Free','Plus','Premium'].map(k=>{const p=d.packages[k]||{};return `<div class=packageAdmin section><div class=space><h3>${esc(k)}</h3><span class="pill ${p.active?'green':'red'}">${p.active?'Active':'Paused'}</span></div><div class=grid3><div class=field><label>الاسم</label><input id=p_${k}_name class=input value="${esc(p.name||k)}"></div><div class=field><label>السعر</label><input id=p_${k}_price class=input type=number step=0.01 value="${Number(p.price||0)}"></div><div class=field><label>المدة بالأيام</label><input id=p_${k}_duration class=input type=number value="${Number(p.durationDays||0)}"></div><div class=field><label>المهام اليومية</label><input id=p_${k}_daily class=input type=number value="${Number(p.dailyTasks||0)}"></div><div class=field><label>الأسبوعية</label><input id=p_${k}_weekly class=input type=number value="${Number(p.weeklyTasks||0)}"></div><div class=field><label>الشهرية</label><input id=p_${k}_monthly class=input type=number value="${Number(p.monthlyTasks||0)}"></div><div class=field><label>الحد لكل مهمة</label><input id=p_${k}_max class=input type=number value="${Number(p.maxPerTask||1)}"></div><div class=field><label>المستوى الأدنى</label><input id=p_${k}_level class=input type=number value="${Number(p.minLevel||0)}"></div><div class=field><label>حد السحب الأدنى</label><input id=p_${k}_wmin class=input type=number step=0.01 value="${Number(p.withdrawalMin||0)}"></div><div class=field><label>حد السحب اليومي</label><input id=p_${k}_wdaily class=input type=number value="${Number(p.withdrawalDailyLimit||1)}"></div><div class=field><label>الأولوية</label><select id=p_${k}_priority class=input><option ${p.priority==='normal'?'selected':''}>normal</option><option ${p.priority==='high'?'selected':''}>high</option><option ${p.priority==='highest'?'selected':''}>highest</option></select></div><div class=field><label>العملة</label><input id=p_${k}_currency class=input value="${esc(p.currency||'JOD')}"></div></div><label class=checkRow><input id=p_${k}_active type=checkbox ${p.active?'checked':''}> فعالة</label><label class=checkRow><input id=p_${k}_visible type=checkbox ${p.visible?'checked':''}> ظاهرة للمستخدمين</label><div class=field><label>المزايا — كل ميزة في سطر</label><textarea id=p_${k}_features class=input rows=5>${esc((p.features||[]).join('\n'))}</textarea></div><button class=btn onclick="savePackage('${k}')">حفظ ${esc(k)}</button></div>`}).join('')}
function packagePayload(k){return {name:$('#p_'+k+'_name').value,price:Number($('#p_'+k+'_price').value),durationDays:Number($('#p_'+k+'_duration').value),dailyTasks:Number($('#p_'+k+'_daily').value),weeklyTasks:Number($('#p_'+k+'_weekly').value),monthlyTasks:Number($('#p_'+k+'_monthly').value),maxPerTask:Number($('#p_'+k+'_max').value),minLevel:Number($('#p_'+k+'_level').value),withdrawalMin:Number($('#p_'+k+'_wmin').value),withdrawalDailyLimit:Number($('#p_'+k+'_wdaily').value),priority:$('#p_'+k+'_priority').value,currency:$('#p_'+k+'_currency').value,active:$('#p_'+k+'_active').checked,visible:$('#p_'+k+'_visible').checked,features:$('#p_'+k+'_features').value.split(/\n+/).map(x=>x.trim()).filter(Boolean)}}
function savePackage(k){emergencyConfirm('حفظ تغييرات باقة '+k+' قد يغير وصول المستخدمين وحدودهم.',`doSavePackage('${k}')`)}async function doSavePackage(k){try{await api('/api/admin/packages',{method:'POST',body:JSON.stringify({key:k,package:packagePayload(k),confirm:$('#emCode').value})});$('#emModal').remove();toast('تم حفظ الباقة');loadPackagesAdmin()}catch(e){toast(e.message)}}
function sandboxPage(){return `<h1>Test Center</h1><p class=subtitle>بيئة اختبار معزولة. اختر أي حساب تجريبي وعدّل Cash / Points / XP / Level مباشرة.</p><div class=card><div class=grid2><div class=field><label>الحساب التجريبي</label><select id=sbUser class=input onchange="loadSandboxUserValues()"><option>جارٍ التحميل...</option></select></div><div class=field><label>المستوى المباشر</label><select id=sbLevel class=input></select></div><div class=field><label>Points</label><input id=sbPoints class=input type=number></div><div class=field><label>XP</label><input id=sbXp class=input type=number></div><div class=field><label>Cash</label><input id=sbCash class=input type=number step="0.01"></div><div class=field><label>الباقة</label><select id=sbPackage class=input><option>Free</option><option>Plus</option><option>Premium</option></select></div></div><button class=btn onclick=saveSandboxUser()>حفظ تغييرات الحساب التجريبي</button><div id=sbMsg class=notice style="margin-top:12px">Sandbox/Test فقط — لا تستخدم هذه الأدوات مع بيانات الإنتاج.</div></div><div class=grid3 section><div class=card><h2>Full Loop</h2><p class=muted>مهمة → Pending → Approved → Reward.</p><button class=btn onclick="runSandbox('full-loop')">تشغيل</button></div><div class=card><h2>Fraud</h2><p class=muted>Warning → Limited → Suspended → Banned.</p><button class="btn secondary" onclick="runSandbox('fraud')">تشغيل</button></div><div class=card><h2>Withdrawal</h2><p class=muted>طلب → اعتماد/رفض → Refund.</p><button class="btn secondary" onclick="runSandbox('withdrawal')">تشغيل</button></div></div><div id=sbBox class=section></div>`}
async function loadSandbox(){try{const d=await api('/api/admin/sandbox/users'),s=$('#sbUser');if(!s)return;s.innerHTML=d.users.map(u=>`<option value="${u.id}">${esc(u.name||u.email||u.id)} — ${esc(u.role)} — ${esc(u.id)}</option>`).join('');$('#sbLevel').innerHTML=d.levels.map(l=>`<option value="${l.id}">${l.name} (${l.minXP} XP)</option>`).join('');loadSandboxUserValues()}catch(e){toast(e.message)}}
function loadSandboxUserValues(){const idv=$('#sbUser')?.value;if(!idv)return;api('/api/admin/sandbox/users').then(d=>{const u=d.users.find(x=>x.id===idv);if(!u)return;$('#sbPoints').value=u.points||0;$('#sbXp').value=u.xp||0;$('#sbCash').value=u.cash||0;$('#sbPackage').value=u.package||'Free';$('#sbLevel').value=u.level?.id||'bronze'}).catch(e=>toast(e.message))}
async function saveSandboxUser(){const confirm=prompt('رمز الأمان الخاص بحسابك');if(confirm===null)return;try{const d=await api('/api/admin/sandbox/user',{method:'POST',body:JSON.stringify({id:$('#sbUser').value,points:Number($('#sbPoints').value),xp:Number($('#sbXp').value),cash:Number($('#sbCash').value),package:$('#sbPackage').value,levelId:$('#sbLevel').value,confirm})});$('#sbMsg').textContent='تم حفظ الحساب التجريبي: '+d.user.id+' — '+d.level.name;toast('تم تحديث Sandbox');loadSandboxUserValues()}catch(e){toast(e.message)}}
function previewPage(){if(state.user.role!=='owner'&&!state.user.permissions.includes('preview'))return `<div class=card><h1>غير مصرح</h1></div>`;return `<div class=hero><div class=preview>PREVIEW / SANDBOX</div><h1>Preview as User</h1><p>بدء المعاينة سينقلك مباشرة إلى واجهة المستخدم الكاملة داخل Sandbox.</p><button class=btn onclick="startPreview()">بدء المعاينة المعزولة</button></div>`}async function startPreview(){try{const d=await api('/api/admin/preview',{method:'POST'});state.preview=true;state.previewData=d;state.portal='user';state.view='dashboard';render()}catch(e){toast(e.message)}}
function advertiserRender(){let c;if(state.view==='dashboard')c=`<div class=hero><h1>مرحباً بك في Tasko for Business</h1><p>إدارة الحملات والطلبات والنتائج من مكان واحد.</p><div class=row><button class=btn onclick="go('campaigns')">عرض حملاتي</button><button class="btn secondary" onclick="requestCampaign()">➕ طلب حملة جديدة</button></div></div><div id=advDash class=grid2>جارٍ التحميل...</div>`;else if(state.view==='campaigns')c=`<div class=space><div><h1>حملاتي</h1><p class=subtitle>تفاصيل الحملات، الميزانيات، الإنفاق، النتائج والتحليلات.</p></div><button class=btn onclick="requestCampaign()">➕ طلب حملة جديدة</button></div><div id=advDash class=section>جارٍ التحميل...</div>`;else if(state.view==='account')c=advertiserAccountPage();else c=advertiserAccountPage();layout(c)}
function advertiserAccountPage(){return `<div class=space><div><h1>معلومات الحساب</h1><p class=subtitle>كل معلومات المعلن الشخصية وحساب الشركة في صفحة مستقلة عن الحملات.</p></div></div><div id=advAccountBox class=section><div class=card>جارٍ تحميل معلومات الحساب...</div></div>`}
async function loadAdvertiserAccount(){try{const d=await api('/api/advertiser/account'),a=d.account,s=d.campaigns,e=$('#advAccountBox');if(!e)return;e.innerHTML=`<div class=grid2><div class=card><h2>المعلومات الشخصية والحسابية</h2><div class=detailList>${[['معرف الحساب',a.id],['معرف المعلن',a.advertiserId],['الاسم / المسؤول',a.name],['البريد الإلكتروني',a.email],['رقم الهاتف',a.phone],['المسمى الوظيفي',a.jobTitle],['الدولة',a.country],['المدينة',a.city],['تاريخ إنشاء الحساب',date(a.createdAt)]].map(x=>`<div class=detailItem><small>${x[0]}</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div></div><div class=card><h2>بيانات الشركة</h2><div class=detailList>${[['اسم الشركة',a.company],['نوع النشاط',a.businessType],['نبذة',a.description],['حالة الحساب',a.status],['التحقق',a.verification],['نوع الحساب',a.vip?'VIP Advertiser':'Regular Advertiser']].map(x=>`<div class=detailItem><small>${x[0]}</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div><div class=grid2 style="margin-top:14px"><div class=reportStat><small>عدد الحملات</small><strong>${s.total}</strong></div><div class=reportStat><small>إجمالي الإنفاق</small><strong>${fmt(s.spend)} JOD</strong></div></div></div></div>`}catch(e){toast(e.message)}}
function advertiserCompanyProfile(){const u=state.user||{};return `<h1>ملف الشركة</h1><p class=subtitle>بيانات الشركة وجهة الاتصال منفصلة عن تفاصيل الحملات.</p><div class=grid2 section><div class=card><h2>${esc(u.company||'شركة المعلن')}</h2><div class=detailList><div class=detailItem><small>المسؤول</small><b>${esc(u.name||'—')}</b></div><div class=detailItem><small>البريد</small><b>${esc(u.email||'—')}</b></div><div class=detailItem><small>الهاتف</small><b>${esc(u.phone||'—')}</b></div><div class=detailItem><small>الحالة</small><b>${esc(u.accountState||'Normal')}</b></div></div></div><div class=card><h2>حساب المعلن</h2><div class=detailList><div class=detailItem><small>النوع</small><b>${state.user?.vip?'VIP Advertiser':'Regular Advertiser'}</b></div><div class=detailItem><small>الدخول</small><b>بوابة Tasko for Business</b></div></div></div></div>`}
function layout(content){const previewMode=!!state.preview,admin=isAdmin()&&!previewMode,items=admin&&!previewMode?[['dashboard','⌂  لوحة التحكم'],['users','👥 المستخدمون'],['admins','🛡️ إدارة الأدمن'],['advertisers','📣 المعلنون'],['campaigns','📊 الحملات'],['tasks','✓ المهام'],['withdrawals','💳 السحوبات'],['support','💬 الدعم والتذاكر'],['fraud','⚠️ المخالفات'],['reports','▥ التقارير والتحليلات'],['activities','⌁ سجل العمليات'],['audit','◷ سجل التدقيق'],['settings','⚙ مركز التحكم'],['packagesAdmin','💳 إدارة الباقات'],['rewardsAdmin','🎁 إدارة المكافآت'],['sandbox','🧪 Test Center'],['preview','👁 Preview as User']]:state.portal==='advertiser'?[['dashboard','⌂ لوحة المعلن'],['campaigns','📊 حملاتي'],['companyProfile','🏢 ملف الشركة']]:[['dashboard','⌂ الرئيسية'],['tasks','✓ المهام'],['packages','◇ الباقات'],['rewards','🎁 متجر المكافآت'],['wallet','💳 المحفظة'],['referrals','↗ الإحالات'],['notifications','🔔 الإشعارات'],['support','💬 الدعم'],['fairplay','✓ Fair Play'],['profile','◉ الملف الشخصي']];const initial=(state.user?.name||state.user?.company||'T')[0].toUpperCase();root.innerHTML=`<div class="app ${state.user?.package==='Premium'?'premiumTheme':''}"><header class=top>${previewMode?'<div class=preview>PREVIEW / SANDBOX</div>':''}<div class=row><button class=mobileMenu onclick="$('.shell').classList.toggle('open')">☰</button><div class=brand>Task<span>o</span></div></div><div class=topUser><button class="avatar avatarBtn" title="فتح الملف الشخصي" onclick="go(state.portal==='advertiser'?'companyProfile':'profile')">${esc(initial)}</button><span>${esc(state.user?.name||state.user?.company||'')}</span>${previewMode?'<button class="btn danger" onclick="exitPreview()">إنهاء المعاينة</button>':''}<button class="btn ghost" onclick="logout()">خروج</button></div></header><div class=shell><aside><div style="padding:4px 10px 18px"><div style="font-size:13px;color:#8fa5bf">${admin?'CONTROL CENTER':state.portal==='advertiser'?'ADVERTISER PORTAL':'MEMBER AREA'}</div><b style="font-size:17px">${esc(state.user?.name||state.user?.company||'')}</b></div>${nav(items)}</aside><main class=main>${content}</main></div></div>`;afterLayout()}
function userChallenges(u,challenges=[]){const by=(period)=>challenges.filter(x=>x.period===period);const mk=(x)=>{const target=Math.max(1,Number(x.goalTarget)||1),n=Math.min(target,Math.max(0,Number(x.progress)||0)),pct=Math.round(n/target*100);return `<div class=card><div class=space><div><b>${esc(x.title)}</b><small class=muted style="display:block;margin-top:4px">${esc(x.periodLabel||x.period)}</small></div><span class="pill ${pct===100?'green':''}">${n} / ${target}</span></div><div style="height:7px;background:#e9eef5;border-radius:999px;overflow:hidden;margin:14px 0 8px"><div style="width:${pct}%;height:100%;background:#2563eb"></div></div><div class=space><small class=muted>${pct}% مكتمل · ${pct===100?'مكتمل':'باقي '+(target-n)}</small><span class=reward>${fmt(x.points||0)} Points</span></div></div>`};if(!challenges.length)return '';return `<div class="section"><div class=space><div><h2>🎯 المهام الإضافية</h2><p class=muted>تحديات تظهر داخل الرئيسية وتتجدد حسب الدورة التي يحددها الـAdmin.</p></div></div><div class=grid3 style="margin-top:12px">${['daily','weekly','monthly'].flatMap(by).map(mk).join('')}</div></div>`}

async function userRender(){const u=state.user;let c;if(state.view==='dashboard'){let challenges=[];try{const cd=await api('/api/challenges');challenges=cd.challenges||[]}catch(e){console.error(e)}c=`<div class=hero><h1>أهلاً ${esc(u.name)} 👋</h1><p>كل مهمة مكتملة ترفع رصيدك وتزيد XP وتقرّبك من مستوى أعلى.</p><button class=btn onclick="go('tasks')">استكشف المهام</button></div><div class=grid><div class="card metric"><span class=icon>🎁</span><span class=kpi>Points</span><strong>${fmt(u.points)}</strong></div><div class="card metric"><span class=icon>💰</span><span class=kpi>Cash</span><strong>${fmt(u.cash)}</strong></div><div class="card metric"><span class=icon>⚡</span><span class=kpi>XP</span><strong>${fmt(u.xp)}</strong></div><div class="card metric"><span class=kpi>الباقة</span><strong style="font-size:22px">${esc(u.package||'Free')}</strong></div></div><div class=section>${levelBlock(u)}</div>${userChallenges(u,challenges)}<div class="grid2 section"><div class=card><div class=space><div><h2>تقدمك</h2><p class=muted>المستوى مستقل عن الباقة.</p></div><button class="btn secondary" onclick="go('profile')">تفاصيل الحساب</button></div></div><div class=card><div class=space><div><h2>الباقة الحالية</h2><p class=muted>الوصول والحدود حسب الباقة.</p></div><span class=pill>${esc(u.package||'Free')}</span></div><button class="btn" onclick="go('packages')">عرض الباقات</button></div></div>`}else if(state.view==='tasks')c=await tasksPage();else if(state.view==='packages')c=packagesPage();else if(state.view==='rewards')c=await rewardsPage();else if(state.view==='wallet')c=walletPage();else if(state.view==='referrals')c=await referralsPage();else if(state.view==='notifications')c=await notificationsPage();else if(state.view==='support')c=await supportPage();else if(state.view==='fairplay')c=fairPlayPage();else c=profilePage();layout(c)}
function profilePage(){const u=state.user;return `<div class=space><div><h1>${state.portal==='advertiser'?'ملف الشركة':'الملف الشخصي'}</h1><p class=subtitle>${state.portal==='advertiser'?'معلومات الشركة والمسؤول ووسائل التواصل.':'معلومات حسابك الأساسية ومستواك ونشاطك.'}</p></div></div><div class=grid2><div class=card><h2>${esc(u.company||u.name||'الحساب')}</h2><div class=detailList><div class=detailItem><small>الاسم</small><b>${esc(u.name||'—')}</b></div><div class=detailItem><small>البريد الإلكتروني</small><b>${esc(u.email||'—')}</b></div><div class=detailItem><small>رقم الهاتف</small><b>${esc(u.phone||'—')}</b></div>${u.company?`<div class=detailItem><small>الشركة / النشاط</small><b>${esc(u.company)}</b></div>`:''}${u.jobTitle?`<div class=detailItem><small>المسمى الوظيفي</small><b>${esc(u.jobTitle)}</b></div>`:''}${u.businessType?`<div class=detailItem><small>نوع النشاط</small><b>${esc(u.businessType)}</b></div>`:''}${u.description?`<div class=detailItem><small>نبذة</small><b>${esc(u.description)}</b></div>`:''}</div></div><div class=card><h2>حالة الحساب</h2><div class=grid2><div class=reportStat><small>الحالة</small><strong>${esc(u.accountState||'Normal')}</strong></div>${state.portal==='user'?`<div class=reportStat><small>المستوى</small><strong>${esc(u.level?.name||levelInfo(u.xp).name)}</strong></div><div class=reportStat><small>XP</small><strong>${fmt(u.xp)}</strong></div><div class=reportStat><small>Points</small><strong>${fmt(u.points)}</strong></div>`:''}</div></div></div>`}
async function loadAdvDash(){const d=await api('/api/advertiser/dashboard');const cs=d.campaigns||[];const sum=cs.reduce((a,c)=>({budget:a.budget+Number(c.budget||0),spent:a.spent+Number(c.results?.spent||0),clicks:a.clicks+Number(c.results?.clicks||0),conv:a.conv+Number(c.results?.conversions||0)}),{budget:0,spent:0,clicks:0,conv:0});const cards=cs.map(c=>{const pct=Number(c.budget)?Math.min(100,Math.round(Number(c.results?.spent||0)/Number(c.budget)*100)):0;return `<div class=card style="margin:10px 0"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.objective||'حملة')}</small></div><span class="pill ${c.status==='active'?'green':'gold'}">${esc(c.status)}</span></div><div class=grid3 style="margin-top:13px"><div class=reportStat><small>الميزانية</small><strong>${fmt(c.budget)} JOD</strong></div><div class=reportStat><small>المصروف</small><strong>${fmt(c.results?.spent)} JOD</strong></div><div class=reportStat><small>المتبقي</small><strong>${fmt(Math.max(0,Number(c.budget||0)-Number(c.results?.spent||0)))} JOD</strong></div><div class=reportStat><small>النقرات</small><strong>${fmt(c.results?.clicks)}</strong></div><div class=reportStat><small>التحويلات</small><strong>${fmt(c.results?.conversions)}</strong></div><div class=reportStat><small>الإنجاز</small><strong>${pct}%</strong></div></div><div style="height:7px;background:#e9eef5;border-radius:999px;overflow:hidden;margin:12px 0"><div style="width:${pct}%;height:100%;background:#2563eb"></div></div><button class="btn ghost" onclick='openCampaignDetails(${JSON.stringify(c)})'>عرض التفاصيل</button></div>`}).join('');const summary=`<div class="card metric"><span class=kpi>الحملات</span><strong>${fmt(cs.length)}</strong><small class=muted>${fmt(cs.filter(c=>c.status==='active').length)} شغالة · ${fmt(cs.filter(c=>c.status==='pending').length)} قيد المراجعة</small></div><div class="card metric"><span class=kpi>إجمالي الميزانية</span><strong>${fmt(sum.budget)} JOD</strong></div><div class="card metric"><span class=kpi>المصروف</span><strong>${fmt(sum.spent)} JOD</strong></div><div class="card metric"><span class=kpi>المتبقي</span><strong>${fmt(Math.max(0,sum.budget-sum.spent))} JOD</strong></div>`;$('#advDash').innerHTML=state.view==='dashboard'?summary+`<div class=section>${cards||'<div class=card empty>لا توجد حملات بعد.</div>'}</div>`:cards||'<div class=card empty>لا توجد حملات مسندة لحسابك بعد.</div>'}
function campaignChart(c){const b=Math.max(1,Number(c.budget)||1),s=Math.min(b,Number(c.results?.spent||0))/b,k=Math.min(1,Number(c.results?.clicks||0)/Math.max(1,Number(c.results?.clicks||0)+50)),v=Math.min(1,Number(c.results?.conversions||0)/Math.max(1,Number(c.results?.conversions||0)+10));const pts=[0.08,0.2+s*.18,0.38+k*.2,0.62+v*.16,Math.min(.94,.45+s*.35+k*.12+v*.08)];const p=pts.map((y,i)=>`${i*25+5},${92-y*70}`).join(' ');return `<div class=card style="margin-top:14px"><div class=space><h3>منحنى التقدم</h3><span class=pill>${Math.round(s*100)}%</span></div><svg viewBox="0 0 110 100" preserveAspectRatio="none" style="width:100%;height:150px;margin-top:10px" aria-label="Campaign progress chart"><polyline points="${p}" fill="none" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke"/><line x1="5" y1="92" x2="105" y2="92" stroke="currentColor" opacity=".15"/></svg></div>`}
function openCampaignDetails(c){const pct=Number(c.budget)?Math.min(100,Math.round(Number(c.results?.spent||0)/Number(c.budget)*100)):0;const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:90vh;overflow:auto"><div class=space><h2>${esc(c.name)}</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=detailList><div class=detailItem><small>الحالة</small><b>${esc(c.status)}</b></div><div class=detailItem><small>الميزانية</small><b>${fmt(c.budget)} JOD</b></div><div class=detailItem><small>المصروف</small><b>${fmt(c.results?.spent)} JOD</b></div><div class=detailItem><small>المتبقي</small><b>${fmt(Math.max(0,Number(c.budget||0)-Number(c.results?.spent||0)))} JOD</b></div><div class=detailItem><small>النقرات</small><b>${fmt(c.results?.clicks)}</b></div><div class=detailItem><small>التحويلات</small><b>${fmt(c.results?.conversions)}</b></div><div class=detailItem><small>نسبة الإنجاز</small><b>${pct}%</b></div><div class=detailItem><small>البداية</small><b>${date(c.startAt)}</b></div><div class=detailItem><small>النهاية</small><b>${date(c.endAt)}</b></div><div class=detailItem><small>آخر تحديث</small><b>${date(c.updatedAt||c.createdAt)}</b></div></div>${campaignChart(c)}<div class=notice style="margin-top:14px">تفاصيل المستخدمين والمكافآت الفردية وقرارات الرفض والمراجعة الداخلية غير معروضة للمعلن.</div></div>`;document.body.appendChild(m)}
function requestCampaign(){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:90vh;overflow:auto"><div class=space><h2>طلب حملة جديدة</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2><div class=field><label>اسم الحملة</label><input id=rcn class=input></div><div class=field><label>الهدف</label><select id=rco class=input><option value="conversion">Conversions</option><option value="lead">Leads</option><option value="traffic">Traffic</option><option value="video">Video Views</option></select></div><div class=field><label>الميزانية المقترحة</label><input id=rcb class=input type=number min=0></div><div class=field><label>المدة المقترحة بالأيام</label><input id=rcd class=input type=number min=1></div><div class=field><label>نوع المهمة</label><select id=rct class=input><option>video</option><option>survey</option><option>signup</option><option>lead</option><option>testing</option><option>purchase</option></select></div><div class=field><label>الحد الأقصى لكل شخص</label><input id=rcm class=input type=number min=1 value="1"></div></div><div class=field><label>رابط المحتوى / الصفحة</label><input id=rcu class=input placeholder="YouTube أو رابط موقع أو منصة أخرى"></div><div class=field><label>وصف وتعليمات الحملة</label><textarea id=rcx class=input rows=5></textarea></div><button class=btn onclick="submitCampaignRequest()">إرسال الطلب</button></div>`;document.body.appendChild(m)}
async function submitCampaignRequest(){try{const d=await api('/api/advertiser/campaign',{method:'POST',body:JSON.stringify({name:$('#rcn').value,objective:$('#rco').value,budget:$('#rcb').value,startAt:null,endAt:null,taskType:$('#rct').value,maxPerUser:$('#rcm').value,landingUrl:$('#rcu').value,description:$('#rcx').value,conditions:$('#rcx').value})});document.querySelector('.modalBack')?.remove();toast('تم إرسال طلب الحملة للمراجعة');go('campaigns')}catch(e){toast(e.message)}}
function rewardsAdminPage(){return `<h1>إدارة المكافآت</h1><p class=subtitle>Owner يقدر ينشئ ويعدل ويوقف ويحذف عروض متجر المكافآت. كل تعديل حساس يحتاج كود التأكيد الثاني.</p><div class=card><h2>إضافة مكافأة</h2><div class=grid2><div class=field><label>اسم المكافأة</label><input id=rn class=input placeholder=مثال: خصم 10%></div><div class=field><label>الوصف</label><input id=rd class=input></div><div class=field><label>الشريك</label><select id=rp class=input></select></div><div class=field><label>النقاط المطلوبة</label><input id=rc class=input type=number min=0 value=500></div><div class=field><label>الحد الأدنى للمستوى</label><input id=rl class=input type=number min=0 value=0></div><div class=field><label>الباقة المطلوبة</label><select id=rpg class=input><option>Free</option><option>Plus</option><option>Premium</option></select></div><div class=field><label>عدد مرات الاستخدام لكل مستخدم</label><input id=ru class=input type=number min=1 value=1></div><div class=field><label>نوع الاسترداد</label><select id=rt class=input><option value=code>Code</option><option value=qr>QR</option><option value=manual>Manual</option></select></div></div><label style=display:block;margin:10px 0><input id=ra type=checkbox checked> مفعلة</label><button class=btn onclick=addReward()>إضافة المكافأة</button></div><div id=rewardsAdminBox class=section>جارٍ تحميل المكافآت...</div>`}
async function loadRewardsAdmin(){const e=$('#rewardsAdminBox');if(!e)return;try{const d=await api('/api/admin/rewards');$('#rp').innerHTML='<option value="">بدون شريك</option>'+d.partners.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');e.innerHTML=d.offers.map(o=>`<div class=card style="margin:10px 0"><div class=space><div><h2>${esc(o.title)}</h2><small class=muted>${esc(o.partner||'بدون شريك')} · ${fmt(o.pointsCost)} Points · ${levelLabel(o)}+</small></div><span class="pill ${o.active?'green':'red'}">${o.active?'مفعلة':'موقوفة'}</span></div><p>${esc(o.description||'')}</p><div class=taskMeta><span class=pill>الباقة: ${esc(o.packageMin||'Free')}</span><span class=pill>الاستخدام: ${fmt(o.usesPerUser||1)}</span><span class=pill>${esc(o.redemptionType||'code')}</span></div><div class=row style="margin-top:10px"><button class="btn secondary" onclick='editReward(${JSON.stringify(o)})'>تعديل</button><button class="btn ${o.active?'danger':'secondary'}" onclick="toggleReward('${esc(o.id)}',${!o.active})">${o.active?'إيقاف':'تفعيل'}</button><button class="btn danger" onclick="deleteReward('${esc(o.id)}')">حذف</button></div></div>`).join('')||'<div class=card empty>لا توجد مكافآت.</div>'}catch(err){e.innerHTML='<div class=card empty>تعذر تحميل المكافآت.</div>';toast(err.message)}}
function editReward(o){const title=prompt('اسم المكافأة',o.title);if(title===null)return;const description=prompt('الوصف',o.description||'');if(description===null)return;const points=prompt('النقاط المطلوبة',o.pointsCost);if(points===null)return;const levelMin=prompt('الحد الأدنى للمستوى',o.levelMin||0);if(levelMin===null)return;const packageMin=prompt('الباقة المطلوبة: Free / Plus / Premium',o.packageMin||'Free');if(packageMin===null)return;const uses=prompt('عدد الاستخدامات لكل مستخدم',o.usesPerUser||1);if(uses===null)return;const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;api('/api/admin/rewards/update',{method:'POST',body:JSON.stringify({id:o.id,title,description,pointsCost:Number(points),levelMin:Number(levelMin),packageMin,usesPerUser:Number(uses),confirm})}).then(()=>{toast('تم تعديل المكافأة');render()}).catch(e=>toast(e.message))}
async function addReward(){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/rewards',{method:'POST',body:JSON.stringify({title:$('#rn').value,description:$('#rd').value,partnerId:$('#rp').value,pointsCost:Number($('#rc').value)||0,levelMin:Number($('#rl').value)||0,packageMin:$('#rpg').value,usesPerUser:Number($('#ru').value)||1,redemptionType:$('#rt').value,active:$('#ra').checked,confirm})});toast('تمت إضافة المكافأة');render()}catch(e){toast(e.message)}}
async function toggleReward(id,active){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/rewards/update',{method:'POST',body:JSON.stringify({id,active,confirm})});toast(active?'تم تفعيل المكافأة':'تم إيقاف المكافأة');render()}catch(e){toast(e.message)}}
async function deleteReward(id){if(!confirm('حذف المكافأة نهائياً؟'))return;const code=prompt('رمز التأكيد الأمني من 4 أرقام');if(code===null)return;try{await api('/api/admin/rewards/delete',{method:'POST',body:JSON.stringify({id,confirm:code})});toast('تم حذف المكافأة');render()}catch(e){toast(e.message)}}
function campaignsPage(){return `<h1>الحملات</h1><p class=subtitle>إنشاء حملة كاملة وتجربة مسار التتبع من الحملة إلى المستخدم.</p><div class=card><div class=grid2><div class=field><label>اسم الحملة</label><input id=cn class=input></div><div class=field><label>المعلن</label><select id=ca class=input><option value="">بدون معلن</option></select></div><div class=field><label>نوع الحملة / الهدف</label><select id=co class=input><option value="conversion">Conversion</option><option value="lead">Lead</option><option value="traffic">Traffic</option><option value="video">Video Views</option></select></div><div class=field><label>نوع المهمة</label><select id=ct class=input><option>video</option><option>survey</option><option>signup</option><option>lead</option><option>testing</option><option>purchase</option></select></div><div class=field><label>الميزانية JOD</label><input id=cb class=input type=number min=0></div><div class=field><label>المصروف المبدئي</label><input id=csp class=input type=number min=0 value="0"></div><div class=field><label>تاريخ البداية</label><input id=cs class=input type=date></div><div class=field><label>تاريخ النهاية</label><input id=ce class=input type=date></div><div class=field><label>المكافأة لكل شخص</label><input id=cr class=input type=number min=0></div><div class=field><label>الحد لكل شخص</label><input id=cm class=input type=number min=1 value="1"></div><div class=field><label>XP</label><input id=cxp class=input type=number min=0 value="0"></div><div class=field><label>أقل مستوى XP</label><input id=cl class=input type=number min=0 value="0"></div><div class=field><label>أقل باقة</label><select id=cp class=input><option>Free</option><option>Plus</option><option>Premium</option></select></div><div class=field><label>التحقق</label><select id=cv class=input><option>auto</option><option>pending</option><option>manual</option></select></div><div class=field><label>الحد الأقصى للمشاركين</label><input id=crp class=input type=number min=0 value="0"></div><div class=field><label>المدة المتوقعة بالدقائق</label><input id=cem class=input type=number min=0 value="0"></div></div><div class=field><label>وصف الحملة</label><textarea id=cd class=input rows=3></textarea></div><div class=field><label>التعليمات وشروط الإكمال</label><textarea id=ci class=input rows=4></textarea></div><div class=field><label>المحتوى: رابط فيديو/صفحة</label><input id=cu class=input placeholder="YouTube / رابط منصة / صفحة هبوط"></div><div class=field><label>رابط التتبع / Landing URL</label><input id=clu class=input></div><div class=notice>يمكن تجربة الحملة أولاً داخل Sandbox. البيانات الفردية للمستخدمين وقرارات الرفض تبقى داخل الإدارة.</div><button class=btn style="margin-top:12px" onclick="createCampaign()">إنشاء الحملة</button></div><div id=campBox class=section>جارٍ التحميل...</div>`}
async function createCampaign(){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/campaigns',{method:'POST',body:JSON.stringify({name:$('#cn').value,budget:$('#cb').value,advertiserId:$('#ca').value,objective:$('#co').value,taskType:$('#ct').value,rewardPerPerson:$('#cr').value,maxPerUser:$('#cm').value,xp:$('#cxp').value,levelMin:$('#cl').value,packageMin:$('#cp').value,verification:$('#cv').value,requiredPeople:$('#crp').value,estimatedMinutes:$('#cem').value,startAt:$('#cs').value,endAt:$('#ce').value,description:$('#cd').value,conditions:$('#ci').value,contentUrl:$('#cu').value,landingUrl:$('#clu').value,contentType:$('#ct').value,confirm})});toast('تم إنشاء الحملة');render()}catch(e){toast(e.message)}}
async function loadCampaigns(){const d=await api('/api/admin/campaigns');$('#campBox').innerHTML=d.campaigns.map(c=>{const pct=Number(c.budget)?Math.min(100,Math.round(Number(c.results?.spent||0)/Number(c.budget)*100)):0;return `<div class=card style="margin:10px 0"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.advertiser?.company||'غير مسند')}</small></div><span class="pill ${c.status==='active'?'green':'gold'}">${esc(c.status)}</span></div><div class=grid3 style="margin-top:14px"><div class=reportStat><small>الميزانية</small><strong>${fmt(c.budget)} JOD</strong></div><div class=reportStat><small>المصروف</small><strong>${fmt(c.results?.spent)} JOD</strong></div><div class=reportStat><small>المتبقي</small><strong>${fmt(Math.max(0,Number(c.budget||0)-Number(c.results?.spent||0)))} JOD</strong></div><div class=reportStat><small>النقرات</small><strong>${fmt(c.results?.clicks)}</strong></div><div class=reportStat><small>التحويلات</small><strong>${fmt(c.results?.conversions)}</strong></div><div class=reportStat><small>الإنجاز</small><strong>${pct}%</strong></div></div><div style="height:7px;background:#e9eef5;border-radius:999px;overflow:hidden;margin:12px 0"><div style="width:${pct}%;height:100%;background:#2563eb"></div></div><button class="btn" onclick='openAdminCampaign(${JSON.stringify(c)})'>فتح الحملة</button></div>`}).join('')||'<div class=card empty>لا توجد حملات.</div>'}
function openAdminCampaign(c){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:92vh;overflow:auto"><div class=space><div><h2>${esc(c.name)}</h2><small class=muted>${esc(c.referenceId)}</small></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2><div class=field><label>اسم الحملة</label><input id=ecn class=input value="${esc(c.name)}"></div><div class=field><label>الحالة</label><select id=ecs class=input><option>draft</option><option>pending</option><option>needs_changes</option><option>preparing</option><option>active</option><option>paused</option><option>completed</option><option>rejected</option></select></div><div class=field><label>الميزانية JOD</label><input id=ecb class=input type=number value="${Number(c.budget||0)}"></div><div class=field><label>المصروف JOD</label><input id=ecsp class=input type=number value="${Number(c.results?.spent||0)}"></div><div class=field><label>المكافأة لكل شخص</label><input id=ecr class=input type=number value="${Number(c.rewardPerPerson||0)}"></div><div class=field><label>XP</label><input id=ecxp class=input type=number value="${Number(c.xp||0)}"></div><div class=field><label>أقصى عدد للشخص</label><input id=ecm class=input type=number value="${Number(c.maxPerUser||1)}"></div><div class=field><label>الحد الأدنى للمستوى</label><select id=ecl class=input><option value="bronze">Bronze</option><option value="silver">Silver</option><option value="gold">Gold</option><option value="diamond">Diamond</option></select></div><div class=field><label>أقل باقة</label><select id=ecp class=input><option>Free</option><option>Plus</option><option>Premium</option></select></div><div class=field><label>تاريخ البداية</label><input id=ecsdate class=input type=datetime-local value="${c.startAt?String(c.startAt).slice(0,16):''}"></div><div class=field><label>تاريخ النهاية</label><input id=ecedate class=input type=datetime-local value="${c.endAt?String(c.endAt).slice(0,16):''}"></div><div class=field><label>التحقق</label><select id=ecv class=input><option>auto</option><option>pending</option><option>manual</option></select></div></div><div class=field><label>الوصف</label><textarea id=ecd class=input rows=3>${esc(c.description||'')}</textarea></div><div class=field><label>التعليمات</label><textarea id=eci class=input rows=4>${esc(c.conditions||'')}</textarea></div><div class=field><label>رابط المحتوى</label><input id=ecu class=input value="${esc(c.contentUrl||'')}"></div><div class=field><label>رابط التتبع</label><input id=eclu class=input value="${esc(c.landingUrl||'')}"></div><div class=notice>Reference / Tracking ID: <b>${esc(c.referenceId||'—')}</b> · Tracking: <b>${esc(c.trackingId||'—')}</b></div><div class=row style="margin-top:14px"><button class=btn onclick="saveCampaignEdit('${esc(c.id)}')">حفظ التعديل</button><button class="btn secondary" onclick="campaignDecision('${esc(c.id)}','active')">اعتماد ونشر</button><button class="btn ghost" onclick="campaignDecision('${esc(c.id)}','paused')">إيقاف مؤقت</button><button class="btn danger" onclick="campaignDecision('${esc(c.id)}','rejected')">رفض</button></div></div>`;document.body.appendChild(m);$('#ecs').value=c.status||'pending';$('#ecl').value=c.levelMinId||levelLabel(c).toLowerCase();$('#ecp').value=c.packageMin||'Free';$('#ecv').value=c.verification||'pending'}
async function saveCampaignEdit(id){try{await api('/api/admin/campaigns/update',{method:'POST',body:JSON.stringify({id,name:$('#ecn').value,status:$('#ecs').value,budget:Number($('#ecb').value)||0,spent:Number($('#ecsp').value)||0,rewardPerPerson:Number($('#ecr').value)||0,xp:Number($('#ecxp').value)||0,maxPerUser:Number($('#ecm').value)||1,levelMinId:$('#ecl').value,packageMin:$('#ecp').value,startAt:$('#ecsdate').value||null,endAt:$('#ecedate').value||null,verification:$('#ecv').value,description:$('#ecd').value,conditions:$('#eci').value,contentUrl:$('#ecu').value,landingUrl:$('#eclu').value,confirm:prompt('رمز التأكيد الأمني من 4 أرقام')})});document.querySelector('.modalBack')?.remove();toast('تم تعديل الحملة');render()}catch(e){toast(e.message)}}
async function campaignDecision(id,status){try{await api('/api/admin/campaigns/status',{method:'POST',body:JSON.stringify({id,status,confirm:prompt('رمز التأكيد الأمني من 4 أرقام')})});document.querySelector('.modalBack')?.remove();toast('تم تحديث حالة الحملة');render()}catch(e){toast(e.message)}}
function adminAdvertisers(){return `<h1>المعلنون</h1><p class=subtitle>حسابات الشركات + طلبات إنشاء حسابات المعلنين.</p><div class=grid2><div class=card><h2>إنشاء معلن</h2><div class=field><label>الشركة</label><input id=ac class=input></div><div class=field><label>جهة الاتصال</label><input id=acn class=input></div><div class=field><label>البريد</label><input id=ace class=input type=email></div><div class=field><label>كلمة المرور</label><input id=acp class=input type=password></div><label><input id=vip type=checkbox> VIP Advertiser</label><button class=btn style="margin-top:12px" onclick="createAdv()">إنشاء الحساب</button></div><div id=advBox>جارٍ التحميل...</div></div><div id=reqBox class=section>جارٍ تحميل طلبات المعلنين...</div>`}
async function loadAdv(){const d=await api('/api/admin/advertisers');$('#advBox').innerHTML=d.advertisers.map(a=>`<div class=card style="margin:10px 0"><div class=space><h3>${esc(a.company)}</h3><span class="pill ${a.vip?'gold':'blue'}">${a.vip?'VIP':'Regular'}</span></div><p>${esc(a.email)} · ${esc(a.status)}</p><small class=muted>${date(a.verifiedAt)}</small><button class="btn ghost" style="margin-top:8px" onclick="openAdvertiserProfile('${esc(a.id)}')">فتح الملف</button></div>`).join('')||'<div class=card empty>لا يوجد معلنون.</div>';loadAdvertiserRequests()}
async function loadAdvertiserRequests(){const e=$('#reqBox');if(!e)return;try{const d=await api('/api/admin/advertiser-requests');e.innerHTML=`<div class=card><div class=space><h2>طلبات إنشاء حساب معلن</h2><span class=pill>${fmt(d.requests.length)} طلب</span></div>${d.requests.map(r=>`<div class=detailItem" style="margin:10px 0"><div class=space><div><b>${esc(r.company)}</b><small style="display:block">${esc(r.contact)} · ${esc(r.email)} · ${esc(r.phone)}</small></div><span class="pill ${r.status==='pending'?'gold':r.status==='approved'?'green':'red'}">${esc(r.status)}</span></div><button class="btn ghost" style="margin-top:8px" onclick='openAdvertiserRequest(${JSON.stringify(r)})'>فتح الطلب</button></div>`).join('')||'<div class=empty>لا توجد طلبات.</div>'}</div>`}catch(err){e.innerHTML='<div class=card empty>تعذر تحميل طلبات المعلنين.</div>'}}
function openAdvertiserRequest(r){const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:92vh;overflow:auto"><div class=space><h2>تفاصيل طلب المعلن</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=detailList>${[['الشركة',r.company],['المسؤول',r.contact],['المسمى',r.jobTitle],['البريد',r.email],['الهاتف',r.phone],['المجال',r.businessType||r.industry],['النبذة',r.description],['الحالة',r.status]].map(x=>`<div class=detailItem><small>${esc(x[0])}</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div><div class=field style="margin-top:14px"><label>تعديل الحالة</label><select id=arStatus class=input><option value="pending">قيد الانتظار</option><option value="under_review">قيد المراجعة</option><option value="needs_changes">يحتاج تعديلات</option><option value="approved">مقبول</option><option value="rejected">مرفوض</option></select></div><div class=row style="margin-top:14px"><button class=btn onclick="saveAdvertiserRequestStatus('${esc(r.id)}')">حفظ الحالة</button><button class="btn secondary" onclick="processAdvertiserRequest('${esc(r.id)}','approve')">موافقة وإنشاء الحساب</button><button class="btn danger" onclick="processAdvertiserRequest('${esc(r.id)}','reject')">رفض</button></div></div>`;document.body.appendChild(m);$('#arStatus').value=r.status||'pending'}
async function saveAdvertiserRequestStatus(id){try{const d=await api('/api/admin/advertiser-request/status',{method:'POST',body:JSON.stringify({id,status:$('#arStatus').value,confirm:prompt('رمز التأكيد الأمني من 4 أرقام')})});document.querySelector('.modalBack')?.remove();toast('تم تعديل حالة الطلب');render()}catch(e){toast(e.message)}}
async function processAdvertiserRequest(id,decision){const reason=decision==='reject'?prompt('سبب الرفض (اختياري)')||'':'';try{const d=await api('/api/admin/advertiser-request',{method:'POST',body:JSON.stringify({id,decision,reason,confirm:prompt('رمز التأكيد الأمني من 4 أرقام')})});document.querySelector('.modalBack')?.remove();toast(decision==='approve'?'تمت الموافقة على الحساب':'تم تحديث حالة الطلب');if(d.temporaryPassword)alert('كلمة المرور المؤقتة: '+d.temporaryPassword);render()}catch(e){toast(e.message)}}
function adminsPage(){return `<h1>إدارة الأدمن</h1><p class=subtitle>Owner يملك التحكم الكامل بالحسابات والصلاحيات.</p><div class=grid2><div class=card><h2>إضافة Admin</h2><div class=field><label>الاسم</label><input id=adn class=input></div><div class=field><label>البريد</label><input id=ade class=input type=email></div><div class=field><label>كلمة المرور</label><input id=adp class=input type=password></div><div class=field><label>الصلاحيات</label><div id=perms></div></div><button class=btn onclick="createAdmin()">إنشاء Admin</button></div><div id=adminsBox class=card>جارٍ التحميل...</div></div>`}
async function loadAdmins(){const d=await api('/api/admin/admins');$('#adminsBox').innerHTML=`<h2>الحسابات الإدارية</h2><div class=detailItem style="margin:10px 0"><b>Owner</b><small>${esc(d.owner?.email||'')}</small><span class=pill green>Full Access</span></div>${d.admins.map(a=>`<div class=detailItem style="margin:10px 0"><div class=space><div><b>${esc(a.name)}</b><small style="display:block">${esc(a.email)}</small></div><span class=pill>${esc(a.accountState)}</span></div><div class=taskMeta>${(a.permissions||[]).map(p=>`<span class=pill>${esc(p)}</span>`).join('')}</div><div class=row style="margin-top:8px"><button class="btn ghost" onclick="editAdmin('${esc(a.id)}')">تعديل</button><button class="btn secondary" onclick="adminResetPassword('${esc(a.id)}')">تغيير كلمة المرور</button><button class="btn danger" onclick="toggleAdmin('${esc(a.id)}','${a.accountState==='Normal'?'Suspended':'Normal'}')">${a.accountState==='Normal'?'تعطيل':'تفعيل'}</button></div></div>`).join('')}`}
function editAdmin(id){const a=prompt('الصلاحيات مفصولة بفواصل\nusers,tasks,campaigns,...');if(a===null)return;updateAdmin(id,{permissions:a.split(',').map(x=>x.trim()).filter(Boolean)})}async function updateAdmin(id,data){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/admins/update',{method:'POST',body:JSON.stringify({id,...data,confirm})});toast('تم تحديث الأدمن');render()}catch(e){toast(e.message)}}function toggleAdmin(id,stateVal){updateAdmin(id,{accountState:stateVal})}async function adminResetPassword(id){const np=prompt('كلمة المرور الجديدة');if(!np)return;const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{await api('/api/admin/admins/password',{method:'POST',body:JSON.stringify({id,password:np,confirm})});toast('تم تغيير كلمة المرور');render()}catch(e){toast(e.message)}}
function usersPage(){return `<h1>المستخدمون</h1><p class=subtitle>افتح أي حساب لرؤية ملفه وإجراءاته.</p><div class=card><div class=searchRow><input id=uq class=input placeholder="بحث" oninput="loadUsers()"><select id=us class=input onchange="loadUsers()"><option value="">كل الحالات</option><option>Normal</option><option>Limited</option><option>Suspended</option><option>Banned</option></select><button class="btn secondary" onclick="loadUsers()">تحديث</button></div></div><div id=usersBox class=section>جارٍ التحميل...</div>`}
async function loadUsers(){const d=await api('/api/admin/users?q='+encodeURIComponent($('#uq')?.value||'')+'&state='+encodeURIComponent($('#us')?.value||''));$('#usersBox').innerHTML=d.users.map(u=>`<div class=card style="margin:10px 0"><div class=space><div><h3>${esc(u.name)}</h3><small>${esc(u.email)}</small></div><span class=pill>${esc(u.accountState)}</span></div><div class=taskMeta><span class=pill>${esc(u.level?.name||levelInfo(u.xp).name)}</span><span class=pill>${fmt(u.points)} Points</span><span class=pill>${esc(u.package||'Free')}</span></div><button class="btn ghost" style="margin-top:10px" onclick="openAdminPerson('${esc(u.id)}')">👁 فتح الملف</button></div>`).join('')||'<div class=card empty>لا يوجد مستخدمون.</div>'}
async function openAdminPerson(id){try{const d=await api('/api/admin/user/'+encodeURIComponent(id));const u=d.user;const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:92vh;overflow:auto"><div class=space><h2>${esc(u.company||u.name)}</h2><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2><div class=card><div class=detailList>${[['الاسم',u.name],['البريد',u.email],['الهاتف',u.phone],['الحالة',u.accountState],['الباقة',u.package||'Free'],['المستوى',u.level?.name||levelInfo(u.xp).name],['XP',u.xp||0],['Points',u.points||0],['Cash',u.cash||0],['الشركة',u.company]].filter(x=>x[1]!==undefined).map(x=>`<div class=detailItem><small>${esc(x[0])}</small><b>${esc(x[1])}</b></div>`).join('')}</div></div><div class=card><h3>تبديل الباقة — اختبار Owner</h3><p class=muted>تغيير الباقة فقط، بدون Reset لأي بيانات.</p><div class=row><button class="btn ${u.package==='Free'?'secondary':''}" onclick="switchTestPackage('${esc(u.id)}','Free')">Free</button><button class="btn ${u.package==='Plus'?'secondary':''}" onclick="switchTestPackage('${esc(u.id)}','Plus')">Plus</button><button class="btn ${u.package==='Premium'?'secondary':''}" onclick="switchTestPackage('${esc(u.id)}','Premium')">Premium</button></div></div></div></div>`;document.body.appendChild(m)}catch(e){toast(e.message)}}
async function switchTestPackage(id,pkg){const confirm=prompt('رمز التأكيد الأمني من 4 أرقام');if(confirm===null)return;try{const d=await api('/api/admin/test-user/package',{method:'POST',body:JSON.stringify({id,package:pkg,confirm})});const m=document.querySelector('.modalBack .modal');if(m){m.querySelectorAll('.detailItem').forEach(x=>{if(x.querySelector('small')?.textContent==='الباقة')x.querySelector('b').textContent=d.user.package});m.querySelectorAll('.row .btn').forEach(b=>b.classList.remove('secondary'));const active=[...m.querySelectorAll('.row .btn')].find(b=>b.textContent.trim()===pkg);active?.classList.add('secondary')}toast('تم تغيير الباقة بدون Reset للبيانات')}catch(e){toast(e.message)}}
function afterLayout(){try{if($('#summaryBox'))loadSummary();if($('#usersBox'))loadUsers();if($('#adBox'))loadAdv();if($('#adminsBox')){loadAdmins();loadPerms()}if($('#advBox'))loadAdv();if($('#reqBox'))loadAdvertiserRequests();if($('#campBox')){loadCampaigns();loadAdvSelect()}if($('#taskAdminBox'))loadAdminTasks();if($('#wBox'))loadW();if($('#sBox'))loadSupport();if($('#fraudBox'))loadFraud();if($('#reportBox'))loadReports();if($('#activityBox'))loadActivities();if($('#auBox'))loadAudit();if($('#emergencyPanel'))loadSettings();if($('#pkgAdmin'))loadPackagesAdmin();if($('#rewardsAdminBox'))loadRewardsAdmin();if($('#advDash'))loadAdvDash();if($('#advAccountBox'))loadAdvertiserAccount();if($('#sbUser'))loadSandbox();if($('#userWithdrawals'))loadUserWithdrawals();if($('#wUser'))loadUserWithdrawals()}catch(e){console.error(e)}}


