const P_META={users:'المستخدمون',tasks:'المهام',campaigns:'الحملات',partners:'الشركاء',withdrawals:'السحوبات',rewards:'المكافآت',referrals:'الإحالات',subscriptions:'الاشتراكات',fraud:'المخالفات',support:'الدعم والتذاكر',reports:'التقارير',audit:'سجل التدقيق',settings:'مركز التحكم',sandbox:'Sandbox',admins:'إدارة الأدمن',advertisers:'المعلنون',preview:'المعاينة'};
