function advertiserCompanyProfile(){const u=state.user||{};return `<h1>ملف الشركة</h1><p class=subtitle>بيانات الشركة منفصلة عن الحملات وباقات المستخدمين.</p><div class=grid2 section><div class=card><h2>${esc(u.company||'شركة المعلن')}</h2><div class=detailList><div class=detailItem><small>Account ID</small><div class=row><b>${esc(u.id||'—')}</b><button class="btn secondary" onclick="copyText('${esc(u.id||'')}')">نسخ</button></div></div><div class=detailItem><small>المسؤول</small><b>${esc(u.name||'—')}</b></div><div class=detailItem><small>البريد</small><b>${esc(u.email||'—')}</b></div><div class=detailItem><small>الهاتف</small><b>${esc(u.phone||'—')}</b></div></div></div><div class=card><h2>حساب المعلن</h2><p class=muted>${u.vip?'VIP Advertiser':'Regular Advertiser'}</p><div class=notice>Free / Plus / Premium غير متاحة للمعلنين.</div></div></div>`}
function usersPage(){return `<h1>المستخدمون</h1><p class=subtitle>ابحث بالاسم أو البريد أو الهاتف أو Account ID.</p><div class=card><div class=searchRow><input id=uq class=input placeholder="بحث بالاسم أو البريد أو الهاتف أو ID" oninput="loadUsers()"><select id=us class=input onchange="loadUsers()"><option value="">كل الحالات</option><option>Normal</option><option>Limited</option><option>Suspended</option><option>Banned</option></select><button class="btn secondary" onclick="loadUsers()">تحديث</button></div></div><div id=usersBox class=section>جارٍ التحميل...</div>`}
async function loadUsers(){const q=$('#uq')?.value||'',s=$('#us')?.value||'';const d=await api('/api/admin/users?q='+encodeURIComponent(q)+'&state='+encodeURIComponent(s));$('#usersBox').innerHTML=`<div class=card><div class=space><h2>النتائج</h2><span class=pill>${d.total} مستخدم</span></div><div class=tableWrap><table class=table><tr><th>المستخدم</th><th>ID</th><th>الحالة</th><th>المستوى</th><th>الباقة</th><th>إجراء</th></tr>${d.users.map(u=>`<tr><td><b>${esc(u.name)}</b><br><small>${esc(u.email)}</small></td><td><div class=row><code>${esc(u.id)}</code><button class="btn secondary copyMini" onclick="copyText('${esc(u.id)}')">نسخ</button></div></td><td>${esc(u.accountState)}</td><td>${esc(u.level?.name||levelInfo(u.xp).name)}</td><td>${esc(u.package||'Free')}</td><td><button class="btn ghost" onclick="openAdminPerson('${esc(u.id)}')">فتح الملف</button></td></tr>`).join('')||'<tr><td colspan=6 class=empty>لا نتائج.</td></tr>'}</table></div></div>`}
function adminDashboard(){return `<div class=hero><h1>Owner Control Center</h1><p>المهمات التي تحتاج إجراء تظهر أولاً.</p><div id=summaryBox class=grid2>جارٍ التحميل...</div></div>`}
function auth(){const p=location.pathname.replace(/\/$/,'')||'/';state.portal=p==='/admin'||p.startsWith('/admin/')?'admin':p==='/advertiser'||p.startsWith('/advertiser/')?'advertiser':'user';const special=state.portal!=='user';if(state.portal==='advertiser'&&!advertiserLoginMode)return advertiserLanding();root.innerHTML=`<div class=auth><div class=authbox><div class=space><div><div class=authBrand>${state.portal==='advertiser'?'Tasko for Business':state.portal==='admin'?'Tasko Control Center':'Tasko'}</div><div class=muted>${state.portal==='advertiser'?'بوابة الشركات والمعلنين':state.portal==='admin'?'بوابة الإدارة والتشغيل':'Do Tasks. Earn More.'}</div></div><span class=pill>${state.portal==='advertiser'?'ADVERTISER':state.portal==='admin'?'ADMIN':'MEMBER'}</span></div><div class=tabs style="margin:24px 0"><button id=loginTab class=active onclick="authMode('login')">تسجيل الدخول</button>${special?'':`<button id=signupTab onclick="authMode('signup')">إنشاء حساب</button>`}</div><div id=authForm></div>${state.portal==='user'?`<div class="card" style="margin-top:16px;background:#f7fafc"><div class=space><div><b>للشركات والمعلنين</b><div class=muted>لديكم بوابة مستقلة.</div></div><button class="btn dark" onclick="location.href='/advertiser'">أعلن معنا</button></div></div>`:''}</div></div>`;authMode('login')}
async function openAdvertiserProfile(idv){try{const d=await api('/api/admin/advertiser/'+encodeURIComponent(idv)),a=d.advertiser,cs=d.campaigns||[];const m=document.createElement('div');m.className='modalBack';m.innerHTML=`<div class=modal style="max-height:92vh;overflow:auto"><div class=space><div><h2>${esc(a.company||'المعلن')}</h2><small class=muted>${esc(a.id)}</small></div><button class="btn ghost" onclick="this.closest('.modalBack').remove()">إغلاق</button></div><div class=grid2 style="margin-top:16px"><div class=card><h3>معلومات الحساب</h3><div class=detailList>${[['المسؤول',a.name],['البريد',a.email],['الهاتف',a.phone],['المسمى الوظيفي',a.jobTitle],['نوع النشاط',a.businessType],['الدولة',a.country],['المدينة',a.city],['تاريخ الإنشاء',date(a.createdAt)],['الحالة',a.status],['التحقق',a.verification]].map(x=>`<div class=detailItem><small>${x[0]}</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div></div><div class=card><h3>الحملات</h3><div class=grid2><div class=reportStat><small>الإجمالي</small><strong>${cs.length}</strong></div><div class=reportStat><small>النشطة</small><strong>${cs.filter(c=>c.status==='active').length}</strong></div><div class=reportStat><small>قيد المراجعة</small><strong>${cs.filter(c=>c.status==='pending').length}</strong></div><div class=reportStat><small>الإنفاق</small><strong>${fmt(cs.reduce((n,c)=>n+Number(c.results?.spent||0),0))} JOD</strong></div></div></div></div></div>`;document.body.appendChild(m)}catch(e){toast(e.message)}}
function goBack(){try{if(document.referrer&&new URL(document.referrer).origin===location.origin&&history.length>1)return history.back()}catch{}location.href=state.portal==='advertiser'?'/advertiser':'/'}
